INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$41d5c33e$SATQ$, $SATQ$f5da42be-3aec-4b8c-8203-d3effdb98683$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is from Beatrice Harraden&rsquo;s 1894 novel <em>Ships that Pass in the Night</em>.</p>
<blockquote>
<p>In an old second-hand bookshop in London, an old man sat reading Gibbon&rsquo;s <em>History of Rome</em>. He did not put down his book when the postman brought him a letter. He just glanced indifferently at the letter, and impatiently at the postman. Zerviah Holme did not like to be interrupted when he was reading Gibbon; and as he was always reading Gibbon, an interruption was always regarded by him as an insult.</p>
</blockquote>$SATQ$, $SATQ$<p>Based on the text, how did Zerviah Holme most likely feel when the letter was delivered?</p>$SATQ$, $SATQ$[{"id":"21f6eb65-3b47-4441-a538-4c238de4cc94","content":"<p>He felt relieved because he had been expecting an important letter.&nbsp;</p>"},{"id":"85fe368b-3132-47ca-92b8-83d2038a6c1f","content":"<p>He felt excited because the letter was from a good friend.</p>"},{"id":"33580415-0c42-40fa-83d1-f7c37fc38e6b","content":"<p>He felt sad because the postman did not stop to talk with him before leaving.&nbsp;</p>"},{"id":"6c8908c6-44c0-47fb-b6fb-9232d811bbe6","content":"<p>He felt annoyed because he was interrupted while reading his favorite author.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["6c8908c6-44c0-47fb-b6fb-9232d811bbe6"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it presents a description of how Zerviah Holme felt that is directly supported by the text. The text states that Holme "did not like to be interrupted" while reading Gibbon and that he considered interruptions to be "an insult." Furthermore, the text suggests that Gibbon is Holme&rsquo;s favorite author because, as the text states, "he was always reading Gibbon." Thus, Holme would have felt annoyed at having been interrupted when the letter was delivered.</p><p>Choice A is incorrect because the text doesn&rsquo;t suggest that Holme is relieved to receive the letter. Instead, the text states that Holme "just glanced indifferently at the letter," suggesting that the letter wasn&rsquo;t important to him. Choice B is incorrect because the text doesn&rsquo;t suggest that Holme is excited to receive the letter. Instead, the text states that Holme didn&rsquo;t put down his book to receive the letter and that he looked at the letter "indifferently" and at the postman "impatiently." This suggests that Holme isn&rsquo;t excited. Also, there is no mention that Holme knows who sent the letter. Choice C is incorrect because the text doesn&rsquo;t indicate that Holme is sad or that he wants to speak with the postman. Instead, the text describes Holme as looking "impatiently at the postman," which suggests that he wants the postman to leave.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"41d5c33e","external_id":"f5da42be-3aec-4b8c-8203-d3effdb98683","vaultid":null,"uId":"ebdf8fe5-d673-4ba4-97f5-dff7e588ab01","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>The following text is from Beatrice Harraden&rsquo;s 1894 novel <em>Ships that Pass in the Night</em>.</p>\n<blockquote>\n<p>In an old second-hand bookshop in London, an old man sat reading Gibbon&rsquo;s <em>History of Rome</em>. He did not put down his book when the postman brought him a letter. He just glanced indifferently at the letter, and impatiently at the postman. Zerviah Holme did not like to be interrupted when he was reading Gibbon; and as he was always reading Gibbon, an interruption was always regarded by him as an insult.</p>\n</blockquote>","stem":"<p>Based on the text, how did Zerviah Holme most likely feel when the letter was delivered?</p>","answerOptions":[{"id":"21f6eb65-3b47-4441-a538-4c238de4cc94","content":"<p>He felt relieved because he had been expecting an important letter.&nbsp;</p>"},{"id":"85fe368b-3132-47ca-92b8-83d2038a6c1f","content":"<p>He felt excited because the letter was from a good friend.</p>"},{"id":"33580415-0c42-40fa-83d1-f7c37fc38e6b","content":"<p>He felt sad because the postman did not stop to talk with him before leaving.&nbsp;</p>"},{"id":"6c8908c6-44c0-47fb-b6fb-9232d811bbe6","content":"<p>He felt annoyed because he was interrupted while reading his favorite author.</p>"}],"keys":["6c8908c6-44c0-47fb-b6fb-9232d811bbe6"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it presents a description of how Zerviah Holme felt that is directly supported by the text. The text states that Holme \"did not like to be interrupted\" while reading Gibbon and that he considered interruptions to be \"an insult.\" Furthermore, the text suggests that Gibbon is Holme&rsquo;s favorite author because, as the text states, \"he was always reading Gibbon.\" Thus, Holme would have felt annoyed at having been interrupted when the letter was delivered.</p><p>Choice A is incorrect because the text doesn&rsquo;t suggest that Holme is relieved to receive the letter. Instead, the text states that Holme \"just glanced indifferently at the letter,\" suggesting that the letter wasn&rsquo;t important to him. Choice B is incorrect because the text doesn&rsquo;t suggest that Holme is excited to receive the letter. Instead, the text states that Holme didn&rsquo;t put down his book to receive the letter and that he looked at the letter \"indifferently\" and at the postman \"impatiently.\" This suggests that Holme isn&rsquo;t excited. Also, there is no mention that Holme knows who sent the letter. Choice C is incorrect because the text doesn&rsquo;t indicate that Holme is sad or that he wants to speak with the postman. Instead, the text describes Holme as looking \"impatiently at the postman,\" which suggests that he wants the postman to leave.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323036,"updateDate":1730147323036}$SATQ$::jsonb, 1730147323036, 1730147323036),
    ($SATQ$420b82e2$SATQ$, $SATQ$ec1412f8-3519-4337-8321-027633350b57$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>In 2016 biological anthropologist Heather F. Smith and her team investigated the evolution of the appendix, an intestinal organ that is present in some mammals, including humans, but is generally thought to have no function. Studying 533 mammal species, the team found that the appendix has emerged independently across multiple lineages in separate instances and, significantly, hasn&rsquo;t disappeared after emerging in specific lineages. Moreover, the team determined that species with the organ tend to have higher concentrations of lymphoid tissue, which supports immune responses, in the cecum, the organ the appendix is attached to. Therefore, the team hypothesized that the appendix likely <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"78799410-5898-4ae6-ae30-d594dd2e9e07","content":"<p>was once present in many nonmammal species but has since disappeared from those lineages.</p>"},{"id":"2f3a17b8-b90b-426d-8332-c98cc294ee12","content":"<p>has been preserved in certain mammal species because it benefits their immune systems.</p>"},{"id":"2d9471ff-30c8-4073-8f76-4ab89e7b95d6","content":"<p>will emerge in a greater number of mammal species because it may serve a necessary function in the immune system.</p>"},{"id":"bc426fa2-4a03-447a-9832-635ad9f65432","content":"<p>produced higher concentrations of lymphoid tissue in mammals in the past than it does currently.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["2f3a17b8-b90b-426d-8332-c98cc294ee12"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of Smith and colleagues&rsquo; investigation of the evolution and biological role of the appendix. The text indicates that the team found several instances of the appendix emerging and not disappearing in the lineages of various mammal species the team examined. Furthermore, the text states that species that possess an appendix also tend to have relatively high amounts of lymphoid tissue&mdash;a type of tissue that supports immune system function. Taken together, these details strongly support the hypothesis that the appendix has persisted in some species because it has a function that contributes to effective immune responses in those species.</p><p>Choice A is incorrect because the text doesn&rsquo;t address any nonmammalian species. Choice C is incorrect because the text doesn&rsquo;t make predictions about the evolutionary future of the species Smith and colleagues examined, and although the implication of the text is that the appendix likely does serve a function for the immune system, nothing in the text indicates that the appendix will become more widespread in the future. Choice D is incorrect. Although the text does suggest an association between having an appendix and relatively high concentrations of lymphoid tissue, it doesn&rsquo;t claim that the appendix causes the tissue to grow, nor does it address the relative production of the tissue at different periods of time.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"420b82e2","external_id":"ec1412f8-3519-4337-8321-027633350b57","vaultid":null,"uId":"77107d39-018e-4511-902c-cdca74cb05c0","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>In 2016 biological anthropologist Heather F. Smith and her team investigated the evolution of the appendix, an intestinal organ that is present in some mammals, including humans, but is generally thought to have no function. Studying 533 mammal species, the team found that the appendix has emerged independently across multiple lineages in separate instances and, significantly, hasn&rsquo;t disappeared after emerging in specific lineages. Moreover, the team determined that species with the organ tend to have higher concentrations of lymphoid tissue, which supports immune responses, in the cecum, the organ the appendix is attached to. Therefore, the team hypothesized that the appendix likely <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"78799410-5898-4ae6-ae30-d594dd2e9e07","content":"<p>was once present in many nonmammal species but has since disappeared from those lineages.</p>"},{"id":"2f3a17b8-b90b-426d-8332-c98cc294ee12","content":"<p>has been preserved in certain mammal species because it benefits their immune systems.</p>"},{"id":"2d9471ff-30c8-4073-8f76-4ab89e7b95d6","content":"<p>will emerge in a greater number of mammal species because it may serve a necessary function in the immune system.</p>"},{"id":"bc426fa2-4a03-447a-9832-635ad9f65432","content":"<p>produced higher concentrations of lymphoid tissue in mammals in the past than it does currently.</p>"}],"keys":["2f3a17b8-b90b-426d-8332-c98cc294ee12"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of Smith and colleagues&rsquo; investigation of the evolution and biological role of the appendix. The text indicates that the team found several instances of the appendix emerging and not disappearing in the lineages of various mammal species the team examined. Furthermore, the text states that species that possess an appendix also tend to have relatively high amounts of lymphoid tissue&mdash;a type of tissue that supports immune system function. Taken together, these details strongly support the hypothesis that the appendix has persisted in some species because it has a function that contributes to effective immune responses in those species.</p><p>Choice A is incorrect because the text doesn&rsquo;t address any nonmammalian species. Choice C is incorrect because the text doesn&rsquo;t make predictions about the evolutionary future of the species Smith and colleagues examined, and although the implication of the text is that the appendix likely does serve a function for the immune system, nothing in the text indicates that the appendix will become more widespread in the future. Choice D is incorrect. Although the text does suggest an association between having an appendix and relatively high concentrations of lymphoid tissue, it doesn&rsquo;t claim that the appendix causes the tissue to grow, nor does it address the relative production of the tissue at different periods of time.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323033,"updateDate":1730147323033}$SATQ$::jsonb, 1730147323033, 1730147323033),
    ($SATQ$4411e15b$SATQ$, $SATQ$41e246d6-ff3c-448d-8852-1127eaf889c0$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Fiber Characteristics of Mouflon, Navajo-Churro, and Spanish Merino Sheep</p></caption><thead><tr><th scope="col" style="text-align: center;vertical-align: bottom;">Type of sheep</th><th scope="col" style="text-align: center;vertical-align: bottom;">Diameter of outer coat fibers (in microns)</th><th scope="col" style="text-align: center;vertical-align: bottom;">Diameter of inner coat fibers (in microns)</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">Spanish Merino</th><td style="text-align: center;">19&ndash;24</td><td style="text-align: center;">17&ndash;21</td></tr><tr><th scope="row" style="text-align: left;">Navajo-Churro</th><td style="text-align: center;">35 or higher</td><td style="text-align: center;">10&ndash;35</td></tr><tr><th scope="row" style="text-align: left;">Mouflon</th><td style="text-align: center;">150</td><td style="text-align: center;">15</td></tr></tbody></table></figure></p>
<p>Domestic sheep&rsquo;s wild ancestor, the mouflon, has a coarse outer coat and an inner coat of wool fiber that is finer in diameter and therefore much softer. In some domestic breeds, such as the Spanish Merino, the outer fiber is only marginally coarser than the inner, and the wool is soft overall. Thus, Merino wool is ideal for delicate garments worn against the skin. Meanwhile, the Navajo-Churro has been selected to retain the marked distinction between outer and inner fiber that the Merino has lost. Being coarser than Merino wool overall, Navajo-Churro wool yields a more durable yarn, which <span lang="nv">Din&eacute;</span> (Navajo) weavers use in their celebrated rugs. Yet a comparison of the fiber characteristics of all three sheep reveals that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the table to complete the text?</p>$SATQ$, $SATQ$[{"id":"57618202-7f59-43c5-9861-d20f785e7a75","content":"<p>the selection process that enabled the Navajo-Churro to retain its somewhat coarse outer fiber also resulted in inner fiber that, at its softest, is softer than either the mouflon&rsquo;s or the Merino&rsquo;s inner fiber.</p>"},{"id":"b4c54706-fd25-4333-8267-ff9f8e126d9c","content":"<p>the Navajo-Churro more closely resembles its ancestor, the mouflon, in the uniform softness of its inner fiber, while the Merino more closely resembles the mouflon in the variable diameter of its outer fiber.&nbsp;</p>"},{"id":"f2498f97-0b9c-4e06-8a59-7007d80aaa73","content":"<p>domestication resulted in a counterintuitive increase in the inner fiber&rsquo;s minimum diameter, making the inner fiber of the Merino and the Navajo-Churro less suitable for delicate garments than the mouflon&rsquo;s inner fiber is.</p>"},{"id":"9412413a-be36-47bb-bfd3-1f859bc76bf5","content":"<p>the domestication of the mouflon and the subsequent selection process that produced the Merino and the Navajo-Churro resulted in greater softness of outer and inner fiber alike.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["57618202-7f59-43c5-9861-d20f785e7a75"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it accurately uses data from the table to complete the statement about the fibers of three types of sheep. The text discusses some qualities of outer and inner fibers of mouflons, Spanish Merino sheep, and Navajo-Churro sheep and indicates that sheep fibers with finer, or smaller, diameters are softer than fibers with larger diameters. The text then sets up a conclusion that can be made by comparing the fibers of all three sheep types. The table shows that the minimum diameter of the Navajo-Churro&rsquo;s inner fibers is 10 microns, which is smaller than the minimum diameters of the inner fibers of both the mouflon (15 microns) and the Spanish Merino (17 microns). Thus, comparing the fiber characteristics of all three sheep reveals that at its softest, the inner fiber of the Navajo-Churro is softer than either the mouflon&rsquo;s or the Merino&rsquo;s inner fiber.</p><p>Choice B is incorrect because it doesn&rsquo;t accurately describe the data in the table. The table shows that the softness of Navajo-Churro inner fiber isn&rsquo;t uniform (since the diameter of Navajo-Churro inner fiber ranges from 10 microns to 35 microns) and that the diameter of the outer fiber of the mouflon isn&rsquo;t variable (rather, it is a uniform 150 microns). Choice C is incorrect because it doesn&rsquo;t accurately describe the data in the table. The text indicates that both Spanish Merino sheep and Navajo-Churro sheep were domesticated from mouflon sheep. The table doesn&rsquo;t show that domestication increased the minimum diameter of inner fibers for both Spanish Merino sheep and Navajo-Churro sheep from the 15-micron diameter of mouflon inner fibers: the minimum diameter of Spanish Merino increased to 17 microns, but the minimum diameter of Navajo-Churro inner fibers <em>decreased</em> to 10 microns. Choice D is incorrect because it doesn&rsquo;t accurately describe the data in the table. The text explains that sheep fibers with finer, or smaller, diameters are softer than fibers with larger diameters. The table does show that Spanish Merino outer fibers are finer, and thus softer, than mouflon outer fibers and that at their finest, Navajo-Churro outer fibers are softer than mouflon outer fibers, but it also shows that Spanish Merino inner fibers are less soft than mouflon inner fibers, since their minimum diameter is greater than 15 microns, and that Navajo-Churro inner fibers can be less soft than mouflon inner fibers, since the diameter ranges up to 35 microns.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"4411e15b","external_id":"41e246d6-ff3c-448d-8852-1127eaf889c0","vaultid":null,"uId":"7266976d-d6be-4e2e-9288-43341f615037","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Fiber Characteristics of Mouflon, Navajo-Churro, and Spanish Merino Sheep</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Type of sheep</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Diameter of outer coat fibers (in microns)</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Diameter of inner coat fibers (in microns)</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">Spanish Merino</th><td style=\"text-align: center;\">19&ndash;24</td><td style=\"text-align: center;\">17&ndash;21</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Navajo-Churro</th><td style=\"text-align: center;\">35 or higher</td><td style=\"text-align: center;\">10&ndash;35</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Mouflon</th><td style=\"text-align: center;\">150</td><td style=\"text-align: center;\">15</td></tr></tbody></table></figure></p>\n<p>Domestic sheep&rsquo;s wild ancestor, the mouflon, has a coarse outer coat and an inner coat of wool fiber that is finer in diameter and therefore much softer. In some domestic breeds, such as the Spanish Merino, the outer fiber is only marginally coarser than the inner, and the wool is soft overall. Thus, Merino wool is ideal for delicate garments worn against the skin. Meanwhile, the Navajo-Churro has been selected to retain the marked distinction between outer and inner fiber that the Merino has lost. Being coarser than Merino wool overall, Navajo-Churro wool yields a more durable yarn, which <span lang=\"nv\">Din&eacute;</span> (Navajo) weavers use in their celebrated rugs. Yet a comparison of the fiber characteristics of all three sheep reveals that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most effectively uses data from the table to complete the text?</p>","answerOptions":[{"id":"57618202-7f59-43c5-9861-d20f785e7a75","content":"<p>the selection process that enabled the Navajo-Churro to retain its somewhat coarse outer fiber also resulted in inner fiber that, at its softest, is softer than either the mouflon&rsquo;s or the Merino&rsquo;s inner fiber.</p>"},{"id":"b4c54706-fd25-4333-8267-ff9f8e126d9c","content":"<p>the Navajo-Churro more closely resembles its ancestor, the mouflon, in the uniform softness of its inner fiber, while the Merino more closely resembles the mouflon in the variable diameter of its outer fiber.&nbsp;</p>"},{"id":"f2498f97-0b9c-4e06-8a59-7007d80aaa73","content":"<p>domestication resulted in a counterintuitive increase in the inner fiber&rsquo;s minimum diameter, making the inner fiber of the Merino and the Navajo-Churro less suitable for delicate garments than the mouflon&rsquo;s inner fiber is.</p>"},{"id":"9412413a-be36-47bb-bfd3-1f859bc76bf5","content":"<p>the domestication of the mouflon and the subsequent selection process that produced the Merino and the Navajo-Churro resulted in greater softness of outer and inner fiber alike.&nbsp;</p>"}],"keys":["57618202-7f59-43c5-9861-d20f785e7a75"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it accurately uses data from the table to complete the statement about the fibers of three types of sheep. The text discusses some qualities of outer and inner fibers of mouflons, Spanish Merino sheep, and Navajo-Churro sheep and indicates that sheep fibers with finer, or smaller, diameters are softer than fibers with larger diameters. The text then sets up a conclusion that can be made by comparing the fibers of all three sheep types. The table shows that the minimum diameter of the Navajo-Churro&rsquo;s inner fibers is 10 microns, which is smaller than the minimum diameters of the inner fibers of both the mouflon (15 microns) and the Spanish Merino (17 microns). Thus, comparing the fiber characteristics of all three sheep reveals that at its softest, the inner fiber of the Navajo-Churro is softer than either the mouflon&rsquo;s or the Merino&rsquo;s inner fiber.</p><p>Choice B is incorrect because it doesn&rsquo;t accurately describe the data in the table. The table shows that the softness of Navajo-Churro inner fiber isn&rsquo;t uniform (since the diameter of Navajo-Churro inner fiber ranges from 10 microns to 35 microns) and that the diameter of the outer fiber of the mouflon isn&rsquo;t variable (rather, it is a uniform 150 microns). Choice C is incorrect because it doesn&rsquo;t accurately describe the data in the table. The text indicates that both Spanish Merino sheep and Navajo-Churro sheep were domesticated from mouflon sheep. The table doesn&rsquo;t show that domestication increased the minimum diameter of inner fibers for both Spanish Merino sheep and Navajo-Churro sheep from the 15-micron diameter of mouflon inner fibers: the minimum diameter of Spanish Merino increased to 17 microns, but the minimum diameter of Navajo-Churro inner fibers <em>decreased</em> to 10 microns. Choice D is incorrect because it doesn&rsquo;t accurately describe the data in the table. The text explains that sheep fibers with finer, or smaller, diameters are softer than fibers with larger diameters. The table does show that Spanish Merino outer fibers are finer, and thus softer, than mouflon outer fibers and that at their finest, Navajo-Churro outer fibers are softer than mouflon outer fibers, but it also shows that Spanish Merino inner fibers are less soft than mouflon inner fibers, since their minimum diameter is greater than 15 microns, and that Navajo-Churro inner fibers can be less soft than mouflon inner fibers, since the diameter ranges up to 35 microns.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771168,"updateDate":1776362771168}$SATQ$::jsonb, 1776362771168, 1776362771168),
    ($SATQ$44da37eb$SATQ$, $SATQ$f6866682-b170-4251-9fd8-8ce1ae56407d$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>The variety of species with adaptations to produce toxins is matched by the variety of uses of those toxins: northern stargazers, for example, use toxins for defense, whereas tiger snakes use toxins for predation and skeleton shrimp use toxins for intraspecific competition. In fact, a species may have adaptations enabling it to produce a toxin with multiple uses. Finding that the venom used by the Panamanian scorpion <em>Centruroides granosus</em> to subdue prey also inhibits growth of the pathogenic bacteria <em>Escherichia coli</em>, Dumas G&aacute;lvez and colleagues conclude that the particular form of venom production observed in <em>C. granosus</em> may have propagated through the species because it mitigates risk during feeding in addition to enhancing predation success.</p>$SATQ$, $SATQ$<p>Which finding, if true, would most directly support G&aacute;lvez and colleagues&rsquo; conclusion?</p>$SATQ$, $SATQ$[{"id":"35b8e5e9-61cb-4607-a91a-cc5413714bb0","content":"<p><em>E. coli</em> does not appear to be virulent for <em>C. granosus</em> even when transmitted from prey captured without the use of venom. &nbsp;</p>"},{"id":"d2259220-4a5c-4e46-92ca-91895c3b0481","content":"<p><em>E. coli</em> is frequently found in species preyed on by <em>C. granosus</em> and can survive exposure to the digestive juices of <em>C. granosus</em>.&nbsp;</p>"},{"id":"ea15822d-57a8-44b1-abb0-6febd9816a73","content":"<p><em>C. granosus</em> appears to be chemically sensitive to prey infected with <em>E. coli</em> and tends to favor uninfected individuals.</p>"},{"id":"6abd9c73-55ab-4da3-890a-5cf65274d74c","content":"<p>Exposure to <em>C. granosus</em> venom also inhibits the growth of nonpathogenic bacteria species common in the native environment of <em>C. granosus</em>.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["d2259220-4a5c-4e46-92ca-91895c3b0481"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it presents a finding that, if true, would most directly support Dumas G&aacute;lvez and colleagues&rsquo; conclusion that the venom produced by the scorpion species <em>Centruroides granosus</em> helps mitigate, or reduce, risk during feeding in addition to enhancing predation success. According to the text, G&aacute;lvez and colleagues found that the venom used by <em>C. granosus</em> both subdues prey and inhibits the growth of <em>Escherichia coli</em>, a pathogen that, if ingested by <em>C. granosus</em>, would presumably cause disease unless neutralized in some way. If it were true that <em>E. coli</em> is commonly found in species preyed on by <em>C. granosus</em> and, moreover, can withstand <em>C. granosus</em>&rsquo;s digestive juices after ingestion, this would suggest that <em>C. granosus</em> likely relies on another mechanism to neutralize <em>E. coli</em> to make <em>E. coli</em>-infected prey safe for consumption by the scorpion species. Given that, as the text states, <em>C. granosus</em>&rsquo;s venom was found to inhibit the pathogen&rsquo;s growth, it therefore follows that the venom provides protection for <em>C. granosus</em> against <em>E. coli</em> that its digestive system wouldn&rsquo;t otherwise provide, making it reasonable to conclude that the trait may have spread through the species because it mitigates risk during feeding.</p><p>Choice A is incorrect because a finding that <em>E. coli</em> doesn&rsquo;t appear to be virulent, or dangerous, for <em>C. granosus</em> even when venom isn&rsquo;t used would weaken rather than strengthen G&aacute;lvez and colleagues&rsquo; conclusion that a particular form of venom production spread in <em>C. granosus</em> in part because it helps reduce risk during feeing, since this finding would suggest that <em>E. coli</em> isn&rsquo;t actually a risk to <em>C. granosus</em> when consuming prey. Choice C is incorrect because a finding that <em>C. granosus</em> can detect and avoid consuming <em>E. coli</em>-infected prey in the first place would suggest that an ability other than venom production is the primary factor that reduces <em>C. granosus</em>&rsquo;s risk when feeding, which would suggest there has been less evolutionary pressure to develop venom that provides protection; thus, this finding wouldn&rsquo;t clearly support the conclusion that <em>C. granosus</em>&rsquo;s form of venom production spread in the species in part because it helps reduce risk during feeding. Choice D is incorrect because G&aacute;lvez and colleagues&rsquo; conclusion focuses on <em>C. granosus</em> venom in relation to the risk of <em>E. coli</em>, and a finding that the venom also inhibits nonpathogenic (not disease-causing) bacteria species, which presumably don&rsquo;t pose a risk if consumed, wouldn&rsquo;t be relevant to the conclusion that <em>C. granosus</em>&rsquo;s particular form of venom production spread in the species in part because it helps reduce risk during feeding.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"44da37eb","external_id":"f6866682-b170-4251-9fd8-8ce1ae56407d","vaultid":null,"uId":"6a3529de-d58c-46de-b892-40dacf83f596","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>The variety of species with adaptations to produce toxins is matched by the variety of uses of those toxins: northern stargazers, for example, use toxins for defense, whereas tiger snakes use toxins for predation and skeleton shrimp use toxins for intraspecific competition. In fact, a species may have adaptations enabling it to produce a toxin with multiple uses. Finding that the venom used by the Panamanian scorpion <em>Centruroides granosus</em> to subdue prey also inhibits growth of the pathogenic bacteria <em>Escherichia coli</em>, Dumas G&aacute;lvez and colleagues conclude that the particular form of venom production observed in <em>C. granosus</em> may have propagated through the species because it mitigates risk during feeding in addition to enhancing predation success.</p>","stem":"<p>Which finding, if true, would most directly support G&aacute;lvez and colleagues&rsquo; conclusion?</p>","answerOptions":[{"id":"35b8e5e9-61cb-4607-a91a-cc5413714bb0","content":"<p><em>E. coli</em> does not appear to be virulent for <em>C. granosus</em> even when transmitted from prey captured without the use of venom. &nbsp;</p>"},{"id":"d2259220-4a5c-4e46-92ca-91895c3b0481","content":"<p><em>E. coli</em> is frequently found in species preyed on by <em>C. granosus</em> and can survive exposure to the digestive juices of <em>C. granosus</em>.&nbsp;</p>"},{"id":"ea15822d-57a8-44b1-abb0-6febd9816a73","content":"<p><em>C. granosus</em> appears to be chemically sensitive to prey infected with <em>E. coli</em> and tends to favor uninfected individuals.</p>"},{"id":"6abd9c73-55ab-4da3-890a-5cf65274d74c","content":"<p>Exposure to <em>C. granosus</em> venom also inhibits the growth of nonpathogenic bacteria species common in the native environment of <em>C. granosus</em>.</p>"}],"keys":["d2259220-4a5c-4e46-92ca-91895c3b0481"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it presents a finding that, if true, would most directly support Dumas G&aacute;lvez and colleagues&rsquo; conclusion that the venom produced by the scorpion species <em>Centruroides granosus</em> helps mitigate, or reduce, risk during feeding in addition to enhancing predation success. According to the text, G&aacute;lvez and colleagues found that the venom used by <em>C. granosus</em> both subdues prey and inhibits the growth of <em>Escherichia coli</em>, a pathogen that, if ingested by <em>C. granosus</em>, would presumably cause disease unless neutralized in some way. If it were true that <em>E. coli</em> is commonly found in species preyed on by <em>C. granosus</em> and, moreover, can withstand <em>C. granosus</em>&rsquo;s digestive juices after ingestion, this would suggest that <em>C. granosus</em> likely relies on another mechanism to neutralize <em>E. coli</em> to make <em>E. coli</em>-infected prey safe for consumption by the scorpion species. Given that, as the text states, <em>C. granosus</em>&rsquo;s venom was found to inhibit the pathogen&rsquo;s growth, it therefore follows that the venom provides protection for <em>C. granosus</em> against <em>E. coli</em> that its digestive system wouldn&rsquo;t otherwise provide, making it reasonable to conclude that the trait may have spread through the species because it mitigates risk during feeding.</p><p>Choice A is incorrect because a finding that <em>E. coli</em> doesn&rsquo;t appear to be virulent, or dangerous, for <em>C. granosus</em> even when venom isn&rsquo;t used would weaken rather than strengthen G&aacute;lvez and colleagues&rsquo; conclusion that a particular form of venom production spread in <em>C. granosus</em> in part because it helps reduce risk during feeing, since this finding would suggest that <em>E. coli</em> isn&rsquo;t actually a risk to <em>C. granosus</em> when consuming prey. Choice C is incorrect because a finding that <em>C. granosus</em> can detect and avoid consuming <em>E. coli</em>-infected prey in the first place would suggest that an ability other than venom production is the primary factor that reduces <em>C. granosus</em>&rsquo;s risk when feeding, which would suggest there has been less evolutionary pressure to develop venom that provides protection; thus, this finding wouldn&rsquo;t clearly support the conclusion that <em>C. granosus</em>&rsquo;s form of venom production spread in the species in part because it helps reduce risk during feeding. Choice D is incorrect because G&aacute;lvez and colleagues&rsquo; conclusion focuses on <em>C. granosus</em> venom in relation to the risk of <em>E. coli</em>, and a finding that the venom also inhibits nonpathogenic (not disease-causing) bacteria species, which presumably don&rsquo;t pose a risk if consumed, wouldn&rsquo;t be relevant to the conclusion that <em>C. granosus</em>&rsquo;s particular form of venom production spread in the species in part because it helps reduce risk during feeding.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061193,"updateDate":1755117061193}$SATQ$::jsonb, 1755117061193, 1755117061193),
    ($SATQ$458b4a11$SATQ$, $SATQ$0ab248c5-2e6c-4eb5-adb7-eec1beae9ae8$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>To understand how temperature change affects microorganism-mediated cycling of soil nutrients in alpine ecosystems, Eva Ka&scaron;tovsk&aacute; et al. collected plant-soil cores in the Tatra Mountains at elevations around 2,100 meters and transplanted them to elevations of 1,700&ndash;1,800 meters, where the mean air temperature was warmer by 2&deg;C. Microorganism-mediated nutrient cycling was accelerated in the transplanted cores; crucially, microorganism community composition was unchanged, allowing Ka&scaron;tovsk&aacute; et al. to attribute the acceleration to temperature-induced increases in microorganism activity.&nbsp;</p>$SATQ$, $SATQ$<p>It can most reasonably be inferred from the text that the finding about the microorganism community composition was important for which reason?</p>$SATQ$, $SATQ$[{"id":"7a401410-ca60-4cba-bb9f-ae47333af05c","content":"<p>It provided preliminary evidence that microorganism-mediated nutrient cycling was accelerated in the transplanted cores.&nbsp;</p>"},{"id":"9191be28-eca6-4a62-928f-aafb462b2e00","content":"<p>It suggested that temperature-induced changes in microorganism activity may be occurring at increasingly high elevations.&nbsp;</p>"},{"id":"ce2261a1-effc-42d9-a274-d0850cb134f8","content":"<p>It ruled out a potential alternative explanation for the acceleration in microorganism-mediated nutrient cycling.&nbsp;</p>"},{"id":"d2a4c38f-3302-454a-974d-f23f3c248798","content":"<p>It clarified that microorganism activity levels in the plant-soil cores varied depending on which microorganisms comprised the community.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["ce2261a1-effc-42d9-a274-d0850cb134f8"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it accurately describes why the finding about the microorganism community composition was important. The text describes an experiment by Eva Ka&scaron;tovsk&aacute; and her team in which they collected plant-soil cores at one elevation and transplanted them to sites at a lower elevation, where the mean air temperature was warmer. Ka&scaron;tovsk&aacute; and her team observed that microorganism-mediated nutrient cycling was accelerated in the transplanted cores and that "crucially, microorganism community composition was unchanged," which allowed the team to attribute the acceleration to changes in microorganism activity brought about by the difference in temperature. This strongly implies that the team wouldn&rsquo;t have been able to make that attribution otherwise, meaning that a change in microorganism composition represented another possible explanation for the acceleration that had to be ruled out.</p><p>Choice A is incorrect. Although the text says microorganism-mediated cycling of soil nutrients increased in the transplanted cores, this is unrelated to what&rsquo;s important about the finding that the microorganism composition didn&rsquo;t change&mdash;that it allowed the team to attribute the change in activity solely to the change in temperature. Choice B is incorrect. Although the text compares activity in one core at two different elevations, the text doesn&rsquo;t address changes in activity at various elevations over time. Choice D is incorrect. Although different microorganisms likely exhibit different levels of activity, the text indicates that there was no change in microorganism composition, and there is nothing in the text about different microorganisms having different activity levels.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"458b4a11","external_id":"0ab248c5-2e6c-4eb5-adb7-eec1beae9ae8","vaultid":null,"uId":"06b6c16c-32a2-4628-8dd6-6fa229b8684a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>To understand how temperature change affects microorganism-mediated cycling of soil nutrients in alpine ecosystems, Eva Ka&scaron;tovsk&aacute; et al. collected plant-soil cores in the Tatra Mountains at elevations around 2,100 meters and transplanted them to elevations of 1,700&ndash;1,800 meters, where the mean air temperature was warmer by 2&deg;C. Microorganism-mediated nutrient cycling was accelerated in the transplanted cores; crucially, microorganism community composition was unchanged, allowing Ka&scaron;tovsk&aacute; et al. to attribute the acceleration to temperature-induced increases in microorganism activity.&nbsp;</p>","stem":"<p>It can most reasonably be inferred from the text that the finding about the microorganism community composition was important for which reason?</p>","answerOptions":[{"id":"7a401410-ca60-4cba-bb9f-ae47333af05c","content":"<p>It provided preliminary evidence that microorganism-mediated nutrient cycling was accelerated in the transplanted cores.&nbsp;</p>"},{"id":"9191be28-eca6-4a62-928f-aafb462b2e00","content":"<p>It suggested that temperature-induced changes in microorganism activity may be occurring at increasingly high elevations.&nbsp;</p>"},{"id":"ce2261a1-effc-42d9-a274-d0850cb134f8","content":"<p>It ruled out a potential alternative explanation for the acceleration in microorganism-mediated nutrient cycling.&nbsp;</p>"},{"id":"d2a4c38f-3302-454a-974d-f23f3c248798","content":"<p>It clarified that microorganism activity levels in the plant-soil cores varied depending on which microorganisms comprised the community.&nbsp;</p>"}],"keys":["ce2261a1-effc-42d9-a274-d0850cb134f8"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it accurately describes why the finding about the microorganism community composition was important. The text describes an experiment by Eva Ka&scaron;tovsk&aacute; and her team in which they collected plant-soil cores at one elevation and transplanted them to sites at a lower elevation, where the mean air temperature was warmer. Ka&scaron;tovsk&aacute; and her team observed that microorganism-mediated nutrient cycling was accelerated in the transplanted cores and that \"crucially, microorganism community composition was unchanged,\" which allowed the team to attribute the acceleration to changes in microorganism activity brought about by the difference in temperature. This strongly implies that the team wouldn&rsquo;t have been able to make that attribution otherwise, meaning that a change in microorganism composition represented another possible explanation for the acceleration that had to be ruled out.</p><p>Choice A is incorrect. Although the text says microorganism-mediated cycling of soil nutrients increased in the transplanted cores, this is unrelated to what&rsquo;s important about the finding that the microorganism composition didn&rsquo;t change&mdash;that it allowed the team to attribute the change in activity solely to the change in temperature. Choice B is incorrect. Although the text compares activity in one core at two different elevations, the text doesn&rsquo;t address changes in activity at various elevations over time. Choice D is incorrect. Although different microorganisms likely exhibit different levels of activity, the text indicates that there was no change in microorganism composition, and there is nothing in the text about different microorganisms having different activity levels.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323036,"updateDate":1730147323036}$SATQ$::jsonb, 1730147323036, 1730147323036),
    ($SATQ$45c03837$SATQ$, $SATQ$fcf354d9-b083-4427-8631-a2cca7e8d2b1$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Outi Tervo and team studied the effect of human-caused noise on narwhals (<em>Monodon monoceros</em>), arctic marine mammals that are sensitive to acoustic changes in their environment. Hypothesizing that elevated sound levels affect foraging among narwhals, Tervo&rsquo;s team compared narwhal diving behaviors in natural sound conditions with those behaviors in two human-caused sound exposure conditions&mdash;ship sounds and ship sounds coupled with sonic pulses. Both exposure conditions resulted in significant decreases in the number and target depth of deep dives (associated with foraging) relative to natural conditions. However, differences between diving behaviors in the two exposure types were negligible, a finding that could be attributed to the fact that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"ce03b2e6-1393-45f9-8c74-ac7b0556cb2e","content":"<p>sonic pulses can be heard at significantly greater ocean depths than ship sounds can.</p>"},{"id":"233a4a85-8a77-4dba-9b94-4d5db68bd5ac","content":"<p>ship sounds contribute so much to the overall sound level that the addition of sonic pulses has little effect on the narwhals&rsquo; auditory environment.</p>"},{"id":"c8bb0c8b-420c-4182-b74d-86082019b030","content":"<p>narwhals forage at shallower depths in the presence of ship sounds alone than in the presence of ship sounds coupled with sonic pulses.</p>"},{"id":"4423e323-90ae-4406-99f0-316159a984ac","content":"<p>the narwhals weren&rsquo;t as sensitive to human-caused sounds as the researchers had predicted.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["233a4a85-8a77-4dba-9b94-4d5db68bd5ac"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of human-caused noise and narwhal behavior. The text establishes that Outi Tervo and team found that while both ship sounds alone and ship sounds coupled with sonic pulses significantly affected narwhal foraging behaviors compared to natural conditions, there were negligible differences between the narwhals&rsquo; responses to the two sound exposure types (a somewhat surprising finding because one might expect that adding sonic pulses would have an even greater impact). It logically follows that if ship sounds are already so loud that adding sonic pulses to them doesn&rsquo;t substantially increase the level of human-caused sound exposure, the two conditions would produce essentially the same behavioral responses because the additional sonic pulses are essentially irrelevant.</p><p>Choice A is incorrect because the fact that sonic pulses are audible at greater depths than are ship sounds would be more likely to help explain a difference&mdash;not a similarity&mdash;in how the narwhals responded to the two types of sound exposure. If at some points during the study the narwhals were at depths where only sonic pulses (but not ship sounds) could be heard, then they might be expected to alter their diving behavior more dramatically in response to those pulses. But since the text reports negligible differences between diving behaviors in the two exposure types, the fact that sonic pulses reach greater depths than do ship sounds has little explanatory power in this context. Choice C is incorrect because the idea that the narwhals foraged at shallower depths in one of the two exposure conditions directly contradicts the information given in the text. The text states that there were negligible differences in the narwhals&rsquo; diving behaviors between the two conditions, meaning that the behaviors were essentially the same. Choice D is incorrect. Although the text states that two conditions with human-caused sounds (ship sounds alone and ship sounds coupled with sonic pulses) had essentially the same effect on narwhals&rsquo; deep dives, this indicates only that sonic pulses didn&rsquo;t meaningfully change the effect of ship sounds, not that the narwhals were less sensitive to human-caused sounds than predicted. Indeed, the text makes it clear that the sounds significantly altered the narwhals&rsquo; behavior.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"45c03837","external_id":"fcf354d9-b083-4427-8631-a2cca7e8d2b1","vaultid":null,"uId":"9eff3493-addb-4574-8fdb-26a49bc5be62","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Outi Tervo and team studied the effect of human-caused noise on narwhals (<em>Monodon monoceros</em>), arctic marine mammals that are sensitive to acoustic changes in their environment. Hypothesizing that elevated sound levels affect foraging among narwhals, Tervo&rsquo;s team compared narwhal diving behaviors in natural sound conditions with those behaviors in two human-caused sound exposure conditions&mdash;ship sounds and ship sounds coupled with sonic pulses. Both exposure conditions resulted in significant decreases in the number and target depth of deep dives (associated with foraging) relative to natural conditions. However, differences between diving behaviors in the two exposure types were negligible, a finding that could be attributed to the fact that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"ce03b2e6-1393-45f9-8c74-ac7b0556cb2e","content":"<p>sonic pulses can be heard at significantly greater ocean depths than ship sounds can.</p>"},{"id":"233a4a85-8a77-4dba-9b94-4d5db68bd5ac","content":"<p>ship sounds contribute so much to the overall sound level that the addition of sonic pulses has little effect on the narwhals&rsquo; auditory environment.</p>"},{"id":"c8bb0c8b-420c-4182-b74d-86082019b030","content":"<p>narwhals forage at shallower depths in the presence of ship sounds alone than in the presence of ship sounds coupled with sonic pulses.</p>"},{"id":"4423e323-90ae-4406-99f0-316159a984ac","content":"<p>the narwhals weren&rsquo;t as sensitive to human-caused sounds as the researchers had predicted.&nbsp;</p>"}],"keys":["233a4a85-8a77-4dba-9b94-4d5db68bd5ac"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of human-caused noise and narwhal behavior. The text establishes that Outi Tervo and team found that while both ship sounds alone and ship sounds coupled with sonic pulses significantly affected narwhal foraging behaviors compared to natural conditions, there were negligible differences between the narwhals&rsquo; responses to the two sound exposure types (a somewhat surprising finding because one might expect that adding sonic pulses would have an even greater impact). It logically follows that if ship sounds are already so loud that adding sonic pulses to them doesn&rsquo;t substantially increase the level of human-caused sound exposure, the two conditions would produce essentially the same behavioral responses because the additional sonic pulses are essentially irrelevant.</p><p>Choice A is incorrect because the fact that sonic pulses are audible at greater depths than are ship sounds would be more likely to help explain a difference&mdash;not a similarity&mdash;in how the narwhals responded to the two types of sound exposure. If at some points during the study the narwhals were at depths where only sonic pulses (but not ship sounds) could be heard, then they might be expected to alter their diving behavior more dramatically in response to those pulses. But since the text reports negligible differences between diving behaviors in the two exposure types, the fact that sonic pulses reach greater depths than do ship sounds has little explanatory power in this context. Choice C is incorrect because the idea that the narwhals foraged at shallower depths in one of the two exposure conditions directly contradicts the information given in the text. The text states that there were negligible differences in the narwhals&rsquo; diving behaviors between the two conditions, meaning that the behaviors were essentially the same. Choice D is incorrect. Although the text states that two conditions with human-caused sounds (ship sounds alone and ship sounds coupled with sonic pulses) had essentially the same effect on narwhals&rsquo; deep dives, this indicates only that sonic pulses didn&rsquo;t meaningfully change the effect of ship sounds, not that the narwhals were less sensitive to human-caused sounds than predicted. Indeed, the text makes it clear that the sounds significantly altered the narwhals&rsquo; behavior.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771171,"updateDate":1776362771171}$SATQ$::jsonb, 1776362771171, 1776362771171),
    ($SATQ$4603d1f7$SATQ$, $SATQ$1a6b528a-47fc-448b-a67f-fc8bcd1e3fda$SATQ$::uuid, $SATQ$950bc600-a6f7-4c93-8793-9617debd544e$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>In their book <em>Smart Pricing</em>, Jagmohan Raju and Z. John Zhang consider musicians&rsquo; use of the nontraditional &ldquo;pay as you wish&rdquo; pricing model. This model generally offers listeners the choice to pay more or less than a suggested price for a song or album&mdash;or even to pay nothing at all. As the authors note, that&rsquo;s the option most listeners chose for an album by the band Harvey Danger. Only about 1% opted to pay for the album, resulting in earnings below the band&rsquo;s expectations. But the authors also discuss musician Jane Siberry, who saw significant earnings from her &ldquo;pay as you wish&rdquo; online music store as a result of many listeners choosing to pay more than the store&rsquo;s suggested prices. Hence, the &ldquo;pay as you wish&rdquo; model may <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"a7ca4313-bfbd-4f12-bd42-42831f0fe197","content":"<p>prove financially successful for some musicians but disappointing for others.</p>"},{"id":"0bf80e57-00b3-4be4-9947-a3851a9d65b4","content":"<p>hold greater financial appeal for bands than for individual musicians.</p>"},{"id":"b319f1af-9c66-4d3f-ada2-24151c89c323","content":"<p>cause most musicians who use the model to lower the suggested prices of their songs and albums over time.</p>"},{"id":"f0ae8825-0ef1-4374-af96-28d44346a177","content":"<p>more strongly reflect differences in certain musicians&rsquo; popularity than traditional pricing models do.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["a7ca4313-bfbd-4f12-bd42-42831f0fe197"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. In one example, musicians made less money than expected by using the &ldquo;pay as you wish&rdquo; model. In the other example, a musician made more money than expected. This suggests that some musicians may have more success than others using the &ldquo;pay as you wish&rdquo; model. </p><p>Choice B is incorrect. This inference isn&rsquo;t supported. In the examples provided, the individual musician was more successful with the &ldquo;pay as you wish&rdquo; model than the band was. Choice C is incorrect. This inference isn&rsquo;t supported. The passage provides no instances in which musicians changed the suggested prices of their songs or albums, nor does it mention this as a possibility. Choice D is incorrect. This inference isn&rsquo;t supported. The text never discusses the differences in popularity of different musicians, so there is no basis to make this inference. </p>$SATQ$, false, 0, $SATQ$OSP-KA-INF-M001$SATQ$, $SATQ$$SATQ$, $SATQ$205574c0-25ba-4e6d-ae8f-ad4cc7629cd9$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"4603d1f7","external_id":"1a6b528a-47fc-448b-a67f-fc8bcd1e3fda","vaultid":"950bc600-a6f7-4c93-8793-9617debd544e","uId":"290470b4-b35f-4484-815e-5877e63f2e48","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>In their book <em>Smart Pricing</em>, Jagmohan Raju and Z. John Zhang consider musicians&rsquo; use of the nontraditional &ldquo;pay as you wish&rdquo; pricing model. This model generally offers listeners the choice to pay more or less than a suggested price for a song or album&mdash;or even to pay nothing at all. As the authors note, that&rsquo;s the option most listeners chose for an album by the band Harvey Danger. Only about 1% opted to pay for the album, resulting in earnings below the band&rsquo;s expectations. But the authors also discuss musician Jane Siberry, who saw significant earnings from her &ldquo;pay as you wish&rdquo; online music store as a result of many listeners choosing to pay more than the store&rsquo;s suggested prices. Hence, the &ldquo;pay as you wish&rdquo; model may <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"a7ca4313-bfbd-4f12-bd42-42831f0fe197","content":"<p>prove financially successful for some musicians but disappointing for others.</p>"},{"id":"0bf80e57-00b3-4be4-9947-a3851a9d65b4","content":"<p>hold greater financial appeal for bands than for individual musicians.</p>"},{"id":"b319f1af-9c66-4d3f-ada2-24151c89c323","content":"<p>cause most musicians who use the model to lower the suggested prices of their songs and albums over time.</p>"},{"id":"f0ae8825-0ef1-4374-af96-28d44346a177","content":"<p>more strongly reflect differences in certain musicians&rsquo; popularity than traditional pricing models do.</p>"}],"keys":["a7ca4313-bfbd-4f12-bd42-42831f0fe197"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. In one example, musicians made less money than expected by using the &ldquo;pay as you wish&rdquo; model. In the other example, a musician made more money than expected. This suggests that some musicians may have more success than others using the &ldquo;pay as you wish&rdquo; model. </p><p>Choice B is incorrect. This inference isn&rsquo;t supported. In the examples provided, the individual musician was more successful with the &ldquo;pay as you wish&rdquo; model than the band was. Choice C is incorrect. This inference isn&rsquo;t supported. The passage provides no instances in which musicians changed the suggested prices of their songs or albums, nor does it mention this as a possibility. Choice D is incorrect. This inference isn&rsquo;t supported. The text never discusses the differences in popularity of different musicians, so there is no basis to make this inference. </p>","parenttemplatename":"OSP-KA-INF-M001","parenttemplateid":"","templateclusterid":"205574c0-25ba-4e6d-ae8f-ad4cc7629cd9","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959368,"updateDate":1691007959368}$SATQ$::jsonb, 1691007959368, 1691007959368),
    ($SATQ$46e45728$SATQ$, $SATQ$a05eaacd-e68b-4293-9cd7-26992ec8deb2$SATQ$::uuid, $SATQ$8b8d7a1e-6a0d-4fc5-ab39-4b25813e9f37$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Daily Distance Traveled by Adult Mountain Lions in Three Seasons</p></caption><thead><tr><th scope="col" style="text-align: center;vertical-align: bottom;">Season</th><th scope="col" style="text-align: center;vertical-align: bottom;">Kilometers per day traveled by adult females</th><th scope="col" style="text-align: center;vertical-align: bottom;">Kilometers per day traveled by adult males</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">cold-dry</th><td style="text-align: center;">9.28</td><td style="text-align: center;">15.81</td></tr><tr><th scope="row" style="text-align: left;">monsoon</th><td style="text-align: center;">12.64</td><td style="text-align: center;">18.93</td></tr><tr><th scope="row" style="text-align: left;">hot-dry</th><td style="text-align: center;">12.48</td><td style="text-align: center;">18.87</td></tr></tbody></table></figure></p>
<p>Wildlife researcher Dana L. Karelus and her colleagues tracked the movements of female and male adult mountain lions over three seasons: the cold-dry season, the hot-dry season, and the monsoon season. They found that the least amount of travel per day occurred in <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the table to complete the statement?</p>$SATQ$, $SATQ$[{"id":"878e9dc0-c6dc-47be-af6d-734805bbed6c","content":"<p>the cold-dry season for both females and males.</p>"},{"id":"599f9cdc-ee2e-46db-ae09-5806fc14d3d6","content":"<p>the cold-dry season for females and the hot-dry season for males.</p>"},{"id":"0bc011a8-1e2d-4a74-86ca-fe001d3edfa7","content":"<p>the hot-dry season for females and the monsoon season for males.</p>"},{"id":"4986fb94-ef23-40f2-8ed5-9ad8c7062c1c","content":"<p>the monsoon season for both females and males.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["878e9dc0-c6dc-47be-af6d-734805bbed6c"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. Females only traveled 9.28 km per day in the cold-dry season, versus 12.64 and 12.48 km per day in the monsoon and hot-dry seasons, respectively. Males only traveled 15.81 km per day per day in the cold-dry season, versus 18.93 and 18.87 km per day in the monsoon and hot-dry seasons, respectively. So, the cold-dry season was the season where both males and females had the least daily travel. </p><p>Choice B is incorrect. Although females traveled least in the cold-dry season, males didn&rsquo;t travel least in the hot-dry season. Instead, they traveled less per day in the cold-dry season as well. Choice C is incorrect. Females had less daily travel in the cold-dry season than in the hot-dry season (9.28 versus 12.48 km per day), and males had less daily travel in the cold-dry season than in the monsoon season (15.81 versus 18.93 km per day). Choice D is incorrect. In fact, both females and males traveled the most kilometers per day in the monsoon season. </p>$SATQ$, false, 0, $SATQ$OSP-KA-QUA-E010$SATQ$, $SATQ$$SATQ$, $SATQ$b1aec3fe-874e-4e80-8a62-baf7a2f21826$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"46e45728","external_id":"a05eaacd-e68b-4293-9cd7-26992ec8deb2","vaultid":"8b8d7a1e-6a0d-4fc5-ab39-4b25813e9f37","uId":"c82af931-cf29-4ade-ba14-df048a028516","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Daily Distance Traveled by Adult Mountain Lions in Three Seasons</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Season</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Kilometers per day traveled by adult females</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Kilometers per day traveled by adult males</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">cold-dry</th><td style=\"text-align: center;\">9.28</td><td style=\"text-align: center;\">15.81</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">monsoon</th><td style=\"text-align: center;\">12.64</td><td style=\"text-align: center;\">18.93</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">hot-dry</th><td style=\"text-align: center;\">12.48</td><td style=\"text-align: center;\">18.87</td></tr></tbody></table></figure></p>\n<p>Wildlife researcher Dana L. Karelus and her colleagues tracked the movements of female and male adult mountain lions over three seasons: the cold-dry season, the hot-dry season, and the monsoon season. They found that the least amount of travel per day occurred in <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most effectively uses data from the table to complete the statement?</p>","answerOptions":[{"id":"878e9dc0-c6dc-47be-af6d-734805bbed6c","content":"<p>the cold-dry season for both females and males.</p>"},{"id":"599f9cdc-ee2e-46db-ae09-5806fc14d3d6","content":"<p>the cold-dry season for females and the hot-dry season for males.</p>"},{"id":"0bc011a8-1e2d-4a74-86ca-fe001d3edfa7","content":"<p>the hot-dry season for females and the monsoon season for males.</p>"},{"id":"4986fb94-ef23-40f2-8ed5-9ad8c7062c1c","content":"<p>the monsoon season for both females and males.&nbsp;</p>"}],"keys":["878e9dc0-c6dc-47be-af6d-734805bbed6c"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. Females only traveled 9.28 km per day in the cold-dry season, versus 12.64 and 12.48 km per day in the monsoon and hot-dry seasons, respectively. Males only traveled 15.81 km per day per day in the cold-dry season, versus 18.93 and 18.87 km per day in the monsoon and hot-dry seasons, respectively. So, the cold-dry season was the season where both males and females had the least daily travel. </p><p>Choice B is incorrect. Although females traveled least in the cold-dry season, males didn&rsquo;t travel least in the hot-dry season. Instead, they traveled less per day in the cold-dry season as well. Choice C is incorrect. Females had less daily travel in the cold-dry season than in the hot-dry season (9.28 versus 12.48 km per day), and males had less daily travel in the cold-dry season than in the monsoon season (15.81 versus 18.93 km per day). Choice D is incorrect. In fact, both females and males traveled the most kilometers per day in the monsoon season. </p>","parenttemplatename":"OSP-KA-QUA-E010","parenttemplateid":"","templateclusterid":"b1aec3fe-874e-4e80-8a62-baf7a2f21826","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959369,"updateDate":1691007959369}$SATQ$::jsonb, 1691007959369, 1691007959369),
    ($SATQ$47f2cddd$SATQ$, $SATQ$59c46e1d-a812-4518-a039-5dfa903f11fe$SATQ$::uuid, $SATQ$b22a8356-025c-4bbb-ad9e-48db852ddb06$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>&ldquo;The Rock and the Sea&rdquo; is an 1893 poem by Charlotte Perkins Gilman. In the poem, a rock is portrayed as intending to confront and restrain the sea: <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which quotation from &ldquo;The Rock and the Sea&rdquo; most effectively illustrates the claim?</p>$SATQ$, $SATQ$[{"id":"a1d64dc7-adff-45da-bdb5-6a5005efc17e","content":"<p>&ldquo;I am the Rock. Black midnight falls; / The terrible breakers rise like walls; / With curling lips and gleaming teeth / They plunge and tear at my bones beneath.&rdquo;</p>"},{"id":"a57e4f3b-e1c3-47c9-93fc-10ed88675f44","content":"<p>&ldquo;I am the Sea. I hold the land / As one holds an apple in his hand, / Hold it fast with sleepless eyes, / Watching the continents sink and rise.&rdquo;</p>"},{"id":"ef5b18ac-b234-4bb8-afe7-8c4d36437143","content":"<p>&ldquo;I am the Rock, presumptuous Sea! / I am set to encounter thee. / Angry and loud or gentle and still, / I am set here to limit thy power, and I will!&rdquo;</p>"},{"id":"cd345a24-2b34-4409-ac9a-456049c83ec3","content":"<p>&ldquo;I am the Sea. The earth I sway; / Granite to me is potter&rsquo;s clay; / Under the touch of my careless waves / It rises in turrets and sinks in caves.&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["ef5b18ac-b234-4bb8-afe7-8c4d36437143"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. This quotation focuses on the rock, which yells at the sea and announces its intent to &ldquo;limit [the sea&rsquo;s] power.&rdquo; This matches the idea of confrontation and restraint in the claim we&rsquo;re trying to support. </p><p>Choice A is incorrect. This choice doesn&rsquo;t illustrate the claim. While this quotation does focus on the rock, it suggests that the rock fears the sea. It lacks the sense of boldness and strength implied by the phrase &ldquo;confront and restrain the sea.&rdquo; Choice B is incorrect. This choice doesn&rsquo;t illustrate the claim. This quotation focuses on the sea, not the rock. Choice D is incorrect. This choice doesn&rsquo;t illustrate the claim. This quotation focuses on the sea, not the rock. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TXT-E001$SATQ$, $SATQ$$SATQ$, $SATQ$247e09c4-2e56-4ebd-8af6-971ef9dfa08c$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"47f2cddd","external_id":"59c46e1d-a812-4518-a039-5dfa903f11fe","vaultid":"b22a8356-025c-4bbb-ad9e-48db852ddb06","uId":"a306215d-ae4e-4055-9833-81f60c0287c9","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>&ldquo;The Rock and the Sea&rdquo; is an 1893 poem by Charlotte Perkins Gilman. In the poem, a rock is portrayed as intending to confront and restrain the sea: <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which quotation from &ldquo;The Rock and the Sea&rdquo; most effectively illustrates the claim?</p>","answerOptions":[{"id":"a1d64dc7-adff-45da-bdb5-6a5005efc17e","content":"<p>&ldquo;I am the Rock. Black midnight falls; / The terrible breakers rise like walls; / With curling lips and gleaming teeth / They plunge and tear at my bones beneath.&rdquo;</p>"},{"id":"a57e4f3b-e1c3-47c9-93fc-10ed88675f44","content":"<p>&ldquo;I am the Sea. I hold the land / As one holds an apple in his hand, / Hold it fast with sleepless eyes, / Watching the continents sink and rise.&rdquo;</p>"},{"id":"ef5b18ac-b234-4bb8-afe7-8c4d36437143","content":"<p>&ldquo;I am the Rock, presumptuous Sea! / I am set to encounter thee. / Angry and loud or gentle and still, / I am set here to limit thy power, and I will!&rdquo;</p>"},{"id":"cd345a24-2b34-4409-ac9a-456049c83ec3","content":"<p>&ldquo;I am the Sea. The earth I sway; / Granite to me is potter&rsquo;s clay; / Under the touch of my careless waves / It rises in turrets and sinks in caves.&rdquo;</p>"}],"keys":["ef5b18ac-b234-4bb8-afe7-8c4d36437143"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. This quotation focuses on the rock, which yells at the sea and announces its intent to &ldquo;limit [the sea&rsquo;s] power.&rdquo; This matches the idea of confrontation and restraint in the claim we&rsquo;re trying to support. </p><p>Choice A is incorrect. This choice doesn&rsquo;t illustrate the claim. While this quotation does focus on the rock, it suggests that the rock fears the sea. It lacks the sense of boldness and strength implied by the phrase &ldquo;confront and restrain the sea.&rdquo; Choice B is incorrect. This choice doesn&rsquo;t illustrate the claim. This quotation focuses on the sea, not the rock. Choice D is incorrect. This choice doesn&rsquo;t illustrate the claim. This quotation focuses on the sea, not the rock. </p>","parenttemplatename":"OSP-KA-TXT-E001","parenttemplateid":"","templateclusterid":"247e09c4-2e56-4ebd-8af6-971ef9dfa08c","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959376,"updateDate":1691007959376}$SATQ$::jsonb, 1691007959376, 1691007959376),
    ($SATQ$4802f6a5$SATQ$, $SATQ$88f09db0-ab6d-48a6-a7a4-02954b32ce99$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Aptamers&mdash;synthetic DNA or RNA molecules that bind to target molecules&mdash;can be used to test for foodborne bacterial pathogens, though their specificity (the probability of returning a negative result in the absence of the focal pathogen) in real-world foods has been unclear. Sandeep Somvanshi <span data-ssml-sub-alias="et al">et al.</span> fabricated test paper incorporating aptamers targeting strain O157:H7 of the bacteria <em>Escherichia coli</em>; the paper shifts from pink to purple as the aptamers bind to target molecules. Somvanshi <span data-ssml-sub-alias="et al">et al.</span> tested the paper in store-bought pear juice they treated with <em><span data-ssml-sub-alias="E">E.</span> coli</em> O157:H7, other strains of <em><span data-ssml-sub-alias="E">E.</span> coli</em>, or other bacteria species. Following exposure, the paper from the O157:H7 test was purple while papers from the other tests were pink, suggesting that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"9daba7fa-94e8-4eb6-8460-b6c12633b5f3","content":"<p>aptamer-based tests in real-world foods are more likely to show a high degree of specificity if the focal pathogen is <em><span data-ssml-sub-alias=\"E\">E.</span> coli</em> O157:H7 than if the focal pathogen is another strain of <em><span data-ssml-sub-alias=\"E\">E.</span> coli</em> or another species.</p>"},{"id":"e25f4c08-fe9c-4998-a396-c5c6d7eb9058","content":"<p>uncertainty about the specificity of aptamer-based tests for pathogens in real-world foods may be due to the similarity between <em><span data-ssml-sub-alias=\"E\">E.</span> coli</em> O157:H7 and other <em><span data-ssml-sub-alias=\"E\">E.</span> coli</em> strains.</p>"},{"id":"f199fd05-3e2a-48d1-8a00-4ff1b33e8058","content":"<p>the specificity of the tests in a real-world food was unaffected by the aptamers&rsquo; tendency to bind to different strains of <em><span data-ssml-sub-alias=\"E\">E.</span> coli</em>.&nbsp;</p>"},{"id":"0a59b720-4be1-4e79-ac9d-304fa2d5229f","content":"<p>the aptamers successfully bound to <em><span data-ssml-sub-alias=\"E\">E.</span>&nbsp;coli</em> O157:H7 and the tests displayed a high degree of specificity in a real-world food.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["0a59b720-4be1-4e79-ac9d-304fa2d5229f"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of aptamers&rsquo; capacity to test for pathogens in food. The text explains that although synthetic aptamer molecules can be used to test for foodborne bacterial pathogens because they bind to target molecules, it hasn&rsquo;t been clear how likely it is that they will indicate a negative result when a target pathogen is absent in real-world foods. The text then indicates that Somvanshi et al. created test paper that changes from pink to purple when aptamers in it bind to a particular strain of <em>E. coli</em> bacteria, O157:H7, and tested it with store-bought pear juice (that is, a real-world food); the paper changed to purple when exposed to juice to which the target pathogen <em>E. coli</em> O157:H7 had been added, but it remained pink when exposed to juice treated with other <em>E. coli</em> strains or other bacteria species. Based on this result, it seems the aptamers in the paper successfully bound to the target (O157:H7) and the tests had a high degree of specificity (providing negative results for samples where the target was absent even though other bacteria were present) when applied to a real-world food.</p><p>Choice A is incorrect because nothing in the text suggests that <em>E. coli</em> O157:H7 differs from other pathogens in a way that makes it more suitable for aptamer-based testing of any kind and that specificity is likely to be lower when aptamer-based tests target other bacteria; the text simply indicates that Somvanshi et al. used O157:H7 as the target for aptamer-based test paper in their study and suggests that the paper had a high degree of specificity. Choice B is incorrect because the text indicates that the specificity of aptamer-based tests in real-world foods is uncertain for pathogens broadly, not just for <em>E. coli</em>, and similarity between strains (of <em>E. coli</em> or of other pathogens) isn&rsquo;t mentioned. Moreover, the results presented in the text suggest that aptamers are actually capable of distinguishing between strains of <em>E. coli</em>, since Somvanshi et al.&rsquo;s paper turned purple when exposed to <em>E. coli</em> O157:H7 and remained pink when exposed to other strains. Choice C is incorrect because the text suggests that the aptamers in the test papers didn&rsquo;t bind to different strains of <em>E. coli</em>. The text explains that the test papers turn purple when the aptamers bind to the targeted pathogen and that in the pear juice tests, the test papers turned purple when exposed to samples with the targeted strain of <em>E. coli</em> (O157:H7) but remained pink when exposed to samples with other strains of <em>E. coli</em>. In other words, the aptamers bound only to the targeted strain, not to the other strains. Further, specificity would be affected if the aptamers had bound to multiple strains and not just the targeted one; that result would cause the specificity to be low.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"4802f6a5","external_id":"88f09db0-ab6d-48a6-a7a4-02954b32ce99","vaultid":null,"uId":"d13f0872-b2be-4e07-b377-52656cfba217","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Aptamers&mdash;synthetic DNA or RNA molecules that bind to target molecules&mdash;can be used to test for foodborne bacterial pathogens, though their specificity (the probability of returning a negative result in the absence of the focal pathogen) in real-world foods has been unclear. Sandeep Somvanshi <span data-ssml-sub-alias=\"et al\">et al.</span> fabricated test paper incorporating aptamers targeting strain O157:H7 of the bacteria <em>Escherichia coli</em>; the paper shifts from pink to purple as the aptamers bind to target molecules. Somvanshi <span data-ssml-sub-alias=\"et al\">et al.</span> tested the paper in store-bought pear juice they treated with <em><span data-ssml-sub-alias=\"E\">E.</span> coli</em> O157:H7, other strains of <em><span data-ssml-sub-alias=\"E\">E.</span> coli</em>, or other bacteria species. Following exposure, the paper from the O157:H7 test was purple while papers from the other tests were pink, suggesting that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"9daba7fa-94e8-4eb6-8460-b6c12633b5f3","content":"<p>aptamer-based tests in real-world foods are more likely to show a high degree of specificity if the focal pathogen is <em><span data-ssml-sub-alias=\"E\">E.</span> coli</em> O157:H7 than if the focal pathogen is another strain of <em><span data-ssml-sub-alias=\"E\">E.</span> coli</em> or another species.</p>"},{"id":"e25f4c08-fe9c-4998-a396-c5c6d7eb9058","content":"<p>uncertainty about the specificity of aptamer-based tests for pathogens in real-world foods may be due to the similarity between <em><span data-ssml-sub-alias=\"E\">E.</span> coli</em> O157:H7 and other <em><span data-ssml-sub-alias=\"E\">E.</span> coli</em> strains.</p>"},{"id":"f199fd05-3e2a-48d1-8a00-4ff1b33e8058","content":"<p>the specificity of the tests in a real-world food was unaffected by the aptamers&rsquo; tendency to bind to different strains of <em><span data-ssml-sub-alias=\"E\">E.</span> coli</em>.&nbsp;</p>"},{"id":"0a59b720-4be1-4e79-ac9d-304fa2d5229f","content":"<p>the aptamers successfully bound to <em><span data-ssml-sub-alias=\"E\">E.</span>&nbsp;coli</em> O157:H7 and the tests displayed a high degree of specificity in a real-world food.&nbsp;</p>"}],"keys":["0a59b720-4be1-4e79-ac9d-304fa2d5229f"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of aptamers&rsquo; capacity to test for pathogens in food. The text explains that although synthetic aptamer molecules can be used to test for foodborne bacterial pathogens because they bind to target molecules, it hasn&rsquo;t been clear how likely it is that they will indicate a negative result when a target pathogen is absent in real-world foods. The text then indicates that Somvanshi et al. created test paper that changes from pink to purple when aptamers in it bind to a particular strain of <em>E. coli</em> bacteria, O157:H7, and tested it with store-bought pear juice (that is, a real-world food); the paper changed to purple when exposed to juice to which the target pathogen <em>E. coli</em> O157:H7 had been added, but it remained pink when exposed to juice treated with other <em>E. coli</em> strains or other bacteria species. Based on this result, it seems the aptamers in the paper successfully bound to the target (O157:H7) and the tests had a high degree of specificity (providing negative results for samples where the target was absent even though other bacteria were present) when applied to a real-world food.</p><p>Choice A is incorrect because nothing in the text suggests that <em>E. coli</em> O157:H7 differs from other pathogens in a way that makes it more suitable for aptamer-based testing of any kind and that specificity is likely to be lower when aptamer-based tests target other bacteria; the text simply indicates that Somvanshi et al. used O157:H7 as the target for aptamer-based test paper in their study and suggests that the paper had a high degree of specificity. Choice B is incorrect because the text indicates that the specificity of aptamer-based tests in real-world foods is uncertain for pathogens broadly, not just for <em>E. coli</em>, and similarity between strains (of <em>E. coli</em> or of other pathogens) isn&rsquo;t mentioned. Moreover, the results presented in the text suggest that aptamers are actually capable of distinguishing between strains of <em>E. coli</em>, since Somvanshi et al.&rsquo;s paper turned purple when exposed to <em>E. coli</em> O157:H7 and remained pink when exposed to other strains. Choice C is incorrect because the text suggests that the aptamers in the test papers didn&rsquo;t bind to different strains of <em>E. coli</em>. The text explains that the test papers turn purple when the aptamers bind to the targeted pathogen and that in the pear juice tests, the test papers turned purple when exposed to samples with the targeted strain of <em>E. coli</em> (O157:H7) but remained pink when exposed to samples with other strains of <em>E. coli</em>. In other words, the aptamers bound only to the targeted strain, not to the other strains. Further, specificity would be affected if the aptamers had bound to multiple strains and not just the targeted one; that result would cause the specificity to be low.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669211,"updateDate":1743430669211}$SATQ$::jsonb, 1743430669211, 1743430669211),
    ($SATQ$485962a6$SATQ$, $SATQ$cfa370f8-719a-49da-9256-4fb44bdaad30$SATQ$::uuid, $SATQ$b377e596-fd2d-43bf-a991-d984cc9b76b1$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Astronomers investigated the Arabia Terra region of Mars because it appears to contain irregularly shaped craters that may have been caused by massive volcanic explosions. In their investigations of Arabia Terra, the researchers found remnants of ash deposits in an amount and thickness that would result from a massive volcanic eruption. However, erosion and past resurfacing events could have modified the surface of the planet. Therefore, <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"64ffe4b1-1eef-469a-ae3f-62b6b376a515","content":"<p>the current makeup of the Arabia Terra region might not accurately reflect the volcanic activity of Mars&rsquo;s past.</p>"},{"id":"9809aeb3-2a66-44de-9b2e-1427ca220a52","content":"<p>eruptions from Mars&rsquo;s volcanoes were likely not as massive as astronomers previously believed.</p>"},{"id":"fb8c898e-e0fb-41d6-9d4c-5f1f87032113","content":"<p>ash was most likely expelled from multiple different volcanoes on Mars&rsquo;s surface.</p>"},{"id":"2005d348-7ad2-4bdb-a3fd-9b08bec29a92","content":"<p>the craters found in the Arabia Terra region were necessarily created by events other than volcanic eruptions.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["64ffe4b1-1eef-469a-ae3f-62b6b376a515"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it presents the conclusion that most logically follows from the text&rsquo;s discussion of the Arabia Terra region of Mars. According to the text, there are craters in Arabia Terra that could be the result of volcanic activity, and researchers have found evidence of ash deposits consistent with a large eruption. The text goes on to note, however, that erosion and other events could have altered the surface of Mars. This observation suggests that current conditions on Mars&rsquo;s surface are not necessarily a reliable guide to past events&mdash;some signs of past events could have been transformed or erased entirely&mdash;and thus the current makeup of Arabia Terra may not accurately reflect past volcanic activity.&nbsp;</p><p>Choice B is incorrect because the text suggests only that past events could have changed Mars&rsquo;s surface such that its current appearance isn&rsquo;t a reliable guide to past activity, not that it&rsquo;s likely that past eruptions were not as massive as astronomers previously believed. Nothing in the text supports a conclusion about the likely size of past eruptions.&nbsp;Choice C is incorrect because the observation that resurfacing events could have changed the appearance of Mars doesn&rsquo;t imply that the ash discussed in the text likely came from multiple volcanoes. Although it&rsquo;s possible that the ash came from different volcanoes, there&rsquo;s no information in the text supporting a conclusion about how likely that possibility is.&nbsp;Choice D is incorrect because nothing in the text suggests that the Arabia Terra craters had to have been created by something other than volcanic eruptions. Although the text does suggest that the evidence consistent with volcanic eruptions shouldn&rsquo;t be taken as definitive proof of past eruptions, that doesn&rsquo;t mean that the craters couldn&rsquo;t have been created by eruptions, only that we can&rsquo;t be certain they were.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-024-INF$SATQ$, $SATQ$$SATQ$, $SATQ$c5712a7e-7aeb-4de4-a73e-6552f7b3882f$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"485962a6","external_id":"cfa370f8-719a-49da-9256-4fb44bdaad30","vaultid":"b377e596-fd2d-43bf-a991-d984cc9b76b1","uId":"ce59c112-d91f-4cc7-add4-d2e1e2bd1b13","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Astronomers investigated the Arabia Terra region of Mars because it appears to contain irregularly shaped craters that may have been caused by massive volcanic explosions. In their investigations of Arabia Terra, the researchers found remnants of ash deposits in an amount and thickness that would result from a massive volcanic eruption. However, erosion and past resurfacing events could have modified the surface of the planet. Therefore, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"64ffe4b1-1eef-469a-ae3f-62b6b376a515","content":"<p>the current makeup of the Arabia Terra region might not accurately reflect the volcanic activity of Mars&rsquo;s past.</p>"},{"id":"9809aeb3-2a66-44de-9b2e-1427ca220a52","content":"<p>eruptions from Mars&rsquo;s volcanoes were likely not as massive as astronomers previously believed.</p>"},{"id":"fb8c898e-e0fb-41d6-9d4c-5f1f87032113","content":"<p>ash was most likely expelled from multiple different volcanoes on Mars&rsquo;s surface.</p>"},{"id":"2005d348-7ad2-4bdb-a3fd-9b08bec29a92","content":"<p>the craters found in the Arabia Terra region were necessarily created by events other than volcanic eruptions.</p>"}],"keys":["64ffe4b1-1eef-469a-ae3f-62b6b376a515"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it presents the conclusion that most logically follows from the text&rsquo;s discussion of the Arabia Terra region of Mars. According to the text, there are craters in Arabia Terra that could be the result of volcanic activity, and researchers have found evidence of ash deposits consistent with a large eruption. The text goes on to note, however, that erosion and other events could have altered the surface of Mars. This observation suggests that current conditions on Mars&rsquo;s surface are not necessarily a reliable guide to past events&mdash;some signs of past events could have been transformed or erased entirely&mdash;and thus the current makeup of Arabia Terra may not accurately reflect past volcanic activity.&nbsp;</p><p>Choice B is incorrect because the text suggests only that past events could have changed Mars&rsquo;s surface such that its current appearance isn&rsquo;t a reliable guide to past activity, not that it&rsquo;s likely that past eruptions were not as massive as astronomers previously believed. Nothing in the text supports a conclusion about the likely size of past eruptions.&nbsp;Choice C is incorrect because the observation that resurfacing events could have changed the appearance of Mars doesn&rsquo;t imply that the ash discussed in the text likely came from multiple volcanoes. Although it&rsquo;s possible that the ash came from different volcanoes, there&rsquo;s no information in the text supporting a conclusion about how likely that possibility is.&nbsp;Choice D is incorrect because nothing in the text suggests that the Arabia Terra craters had to have been created by something other than volcanic eruptions. Although the text does suggest that the evidence consistent with volcanic eruptions shouldn&rsquo;t be taken as definitive proof of past eruptions, that doesn&rsquo;t mean that the craters couldn&rsquo;t have been created by eruptions, only that we can&rsquo;t be certain they were.&nbsp;</p>","parenttemplatename":"OSP-024-INF","parenttemplateid":"","templateclusterid":"c5712a7e-7aeb-4de4-a73e-6552f7b3882f","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959317,"updateDate":1691007959317}$SATQ$::jsonb, 1691007959317, 1691007959317),
    ($SATQ$487a05f8$SATQ$, $SATQ$bad15e98-4169-43d5-9421-374a6231ddfb$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is adapted from Sylvia Acevedo&rsquo;s 2018 memoir <em>Path to the Stars: My Journey from Girl Scout to Rocket Scientist. </em>The narrator is traveling by car with her family to Mexico City. Mario and Laura are her brother and sister.</p>
<blockquote>
<p>Mario and I played games to see how many different license plates we could spot, and Laura liked to look for children in the back seats of the cars we passed. We were used to the forty-five-minute drive to El Paso and familiar with the six-hour ride to Chihuahua, but I wondered what the long journey to Mexico City would be like.</p>
</blockquote>
<p style="text-align: right;"><span class="dap_copyright">&copy;2018 by Sylvia Acevedo</span></p>$SATQ$, $SATQ$<p>According to the text, what did the narrator and Mario do while riding in the car?</p>$SATQ$, $SATQ$[{"id":"4bb11c5c-7d2b-43c4-ae0a-499265adebf0","content":"<p>They read books.&nbsp;</p>"},{"id":"8767bd87-2e95-44a6-8dfb-57b20d1d9c0c","content":"<p>They sang songs.</p>"},{"id":"3a8b1596-b9fb-4507-beca-b733c6b87c83","content":"<p>They went to sleep.</p>"},{"id":"8eddf5a8-9c38-45ac-b918-d50058268e78","content":"<p>They played games.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["8eddf5a8-9c38-45ac-b918-d50058268e78"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most accurately describes what the narrator and Mario did while riding in the car. The text describes a car trip that the narrator is taking with her family. The text states that during the car ride, the narrator and Mario "played games" to see how many different license plates they could spot.</p><p>Choice A is incorrect because the text doesn&rsquo;t mention the narrator and Mario reading during the car ride and instead describes them playing games. Choice B is incorrect because the text doesn&rsquo;t mention the narrator and Mario singing songs during the car ride and instead describes them playing games. Choice C is incorrect because the text doesn&rsquo;t mention the narrator and Mario sleeping during the car ride and instead describes them playing games.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"487a05f8","external_id":"bad15e98-4169-43d5-9421-374a6231ddfb","vaultid":null,"uId":"4933819e-1282-4659-9e4b-3daf80488357","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>The following text is adapted from Sylvia Acevedo&rsquo;s 2018 memoir <em>Path to the Stars: My Journey from Girl Scout to Rocket Scientist. </em>The narrator is traveling by car with her family to Mexico City. Mario and Laura are her brother and sister.</p>\n<blockquote>\n<p>Mario and I played games to see how many different license plates we could spot, and Laura liked to look for children in the back seats of the cars we passed. We were used to the forty-five-minute drive to El Paso and familiar with the six-hour ride to Chihuahua, but I wondered what the long journey to Mexico City would be like.</p>\n</blockquote>\n<p style=\"text-align: right;\"><span class=\"dap_copyright\">&copy;2018 by Sylvia Acevedo</span></p>","stem":"<p>According to the text, what did the narrator and Mario do while riding in the car?</p>","answerOptions":[{"id":"4bb11c5c-7d2b-43c4-ae0a-499265adebf0","content":"<p>They read books.&nbsp;</p>"},{"id":"8767bd87-2e95-44a6-8dfb-57b20d1d9c0c","content":"<p>They sang songs.</p>"},{"id":"3a8b1596-b9fb-4507-beca-b733c6b87c83","content":"<p>They went to sleep.</p>"},{"id":"8eddf5a8-9c38-45ac-b918-d50058268e78","content":"<p>They played games.</p>"}],"keys":["8eddf5a8-9c38-45ac-b918-d50058268e78"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most accurately describes what the narrator and Mario did while riding in the car. The text describes a car trip that the narrator is taking with her family. The text states that during the car ride, the narrator and Mario \"played games\" to see how many different license plates they could spot.</p><p>Choice A is incorrect because the text doesn&rsquo;t mention the narrator and Mario reading during the car ride and instead describes them playing games. Choice B is incorrect because the text doesn&rsquo;t mention the narrator and Mario singing songs during the car ride and instead describes them playing games. Choice C is incorrect because the text doesn&rsquo;t mention the narrator and Mario sleeping during the car ride and instead describes them playing games.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669212,"updateDate":1743430669212}$SATQ$::jsonb, 1743430669212, 1743430669212),
    ($SATQ$4889580c$SATQ$, $SATQ$d15c6de5-ed37-4abd-b581-ad392b36c426$SATQ$::uuid, $SATQ$4ea83ada-5bce-4102-b1d4-8672581ec5e1$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Archaeologists and historians used to believe that the Maya civilization during its Classic period (roughly 250&ndash;900) lacked agricultural marketplaces. One reason for this belief was that these scholars misunderstood the ecology of the regions the Maya inhabited. Marketplaces typically emerge because different individuals or groups want to trade resources they control for resources they don&rsquo;t control. Scholars seriously underestimated the ecological diversity of the Maya landscape and thus assumed that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"8f9674b3-ce4c-4234-958f-6965230825ad","content":"<p>marketplaces likely would not have attracted many traders from outside the regions controlled by the Maya.</p>"},{"id":"af539123-79bc-4b25-a090-65cd058b2d38","content":"<p>farming practices would have been largely the same throughout Maya lands even if the crops people produced varied significantly.&nbsp;</p>"},{"id":"f132f364-4416-4f06-8351-ee6635558388","content":"<p>marketplaces would not have enabled Maya people to acquire many products different from those they already produced.</p>"},{"id":"34827347-7ce6-4333-945b-62dd0bac03de","content":"<p>farmers would trade agricultural products only if they had already produced enough to meet their own needs.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["f132f364-4416-4f06-8351-ee6635558388"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it presents the conclusion that most logically follows from the text&rsquo;s discussion of scholars&rsquo; understanding of Maya ecology and agricultural marketplaces. The text indicates that scholars used to believe that during the Classic period, the Maya civilization didn&rsquo;t have agricultural marketplaces. According to the text, scholars held this view because they misunderstood the ecology of areas where the Maya lived. The text points out that people tend to create marketplaces in order to acquire resources they don&rsquo;t otherwise control. Agricultural marketplaces would have allowed farmers who produced one type of crop to trade that crop for other types of crops that they didn&rsquo;t produce. The text goes on to say, however, that scholars underestimated the ecological diversity of the Maya areas, meaning that scholars thought that the Maya landscape produced a smaller range of resources than it actually produced. Taken together, then, this information suggests that scholars assumed that marketplaces wouldn&rsquo;t have allowed Maya people to acquire products different from the products they already produced: that is, if everyone produced the same array of crops, as scholars mistakenly believed, then there wouldn&rsquo;t have been any need for marketplaces where people could trade those crops. </p><p>Choice A is incorrect because the text doesn&rsquo;t say anything about trade between the Maya and people from outside the regions controlled by the Maya. Although scholars&rsquo; mistaken belief that the Maya lands weren&rsquo;t very ecologically diverse would give those scholars a reason to think that the Maya didn&rsquo;t have marketplaces, it wouldn&rsquo;t lead scholars to assume that traders from outside Maya lands were uninterested in acquiring resources produced by the Maya. Even if the Maya actually did produce only a small array of resources throughout their lands, there is no reason to believe from the text that people outside Maya lands also produced these same resources and thus would have no need to trade with the Maya people. Choice B is incorrect because the text indicates that scholars underestimated the ecological diversity of the Maya lands, which suggests that they mistakenly believed that the Maya produced a relatively small array of resources throughout their territory, not that the crops the Maya produced varied significantly throughout the Maya lands. Although the scholars might have assumed that a lack of ecological diversity suggests that Maya farming practices were largely the same everywhere, the text does not support that they also assumed there was a lot of variation in the crops that Maya people produced. In fact, the text states that marketplaces emerge when people want to obtain resources they don&rsquo;t already control. If it were the case that scholars assumed that the crops Maya people produced varied significantly, this would have led them to conclude that Maya people likely established marketplaces so they could trade for resources they didn&rsquo;t already possess, not that the Maya civilization lacked marketplaces. Choice D is incorrect because nothing in the text suggests that scholars assumed that farmers wouldn&rsquo;t trade their agricultural products unless they had already met their own needs with those products. Instead, the text says that scholars thought that the Maya lands produced a smaller array of resources than they actually did, which the text suggests led scholars to assume that the Maya didn&rsquo;t have any need for marketplaces. The scholars&rsquo; mistaken belief has no bearing on the issue of whether farmers met their own needs before trading their products. </p>$SATQ$, false, 0, $SATQ$OSP-049-INF$SATQ$, $SATQ$$SATQ$, $SATQ$ba9b0527-7faa-4f01-a59c-94782261b9ed$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"4889580c","external_id":"d15c6de5-ed37-4abd-b581-ad392b36c426","vaultid":"4ea83ada-5bce-4102-b1d4-8672581ec5e1","uId":"4098a91c-4f4d-43e3-a881-b7faa5ad750f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Archaeologists and historians used to believe that the Maya civilization during its Classic period (roughly 250&ndash;900) lacked agricultural marketplaces. One reason for this belief was that these scholars misunderstood the ecology of the regions the Maya inhabited. Marketplaces typically emerge because different individuals or groups want to trade resources they control for resources they don&rsquo;t control. Scholars seriously underestimated the ecological diversity of the Maya landscape and thus assumed that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"8f9674b3-ce4c-4234-958f-6965230825ad","content":"<p>marketplaces likely would not have attracted many traders from outside the regions controlled by the Maya.</p>"},{"id":"af539123-79bc-4b25-a090-65cd058b2d38","content":"<p>farming practices would have been largely the same throughout Maya lands even if the crops people produced varied significantly.&nbsp;</p>"},{"id":"f132f364-4416-4f06-8351-ee6635558388","content":"<p>marketplaces would not have enabled Maya people to acquire many products different from those they already produced.</p>"},{"id":"34827347-7ce6-4333-945b-62dd0bac03de","content":"<p>farmers would trade agricultural products only if they had already produced enough to meet their own needs.&nbsp;</p>"}],"keys":["f132f364-4416-4f06-8351-ee6635558388"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it presents the conclusion that most logically follows from the text&rsquo;s discussion of scholars&rsquo; understanding of Maya ecology and agricultural marketplaces. The text indicates that scholars used to believe that during the Classic period, the Maya civilization didn&rsquo;t have agricultural marketplaces. According to the text, scholars held this view because they misunderstood the ecology of areas where the Maya lived. The text points out that people tend to create marketplaces in order to acquire resources they don&rsquo;t otherwise control. Agricultural marketplaces would have allowed farmers who produced one type of crop to trade that crop for other types of crops that they didn&rsquo;t produce. The text goes on to say, however, that scholars underestimated the ecological diversity of the Maya areas, meaning that scholars thought that the Maya landscape produced a smaller range of resources than it actually produced. Taken together, then, this information suggests that scholars assumed that marketplaces wouldn&rsquo;t have allowed Maya people to acquire products different from the products they already produced: that is, if everyone produced the same array of crops, as scholars mistakenly believed, then there wouldn&rsquo;t have been any need for marketplaces where people could trade those crops. </p><p>Choice A is incorrect because the text doesn&rsquo;t say anything about trade between the Maya and people from outside the regions controlled by the Maya. Although scholars&rsquo; mistaken belief that the Maya lands weren&rsquo;t very ecologically diverse would give those scholars a reason to think that the Maya didn&rsquo;t have marketplaces, it wouldn&rsquo;t lead scholars to assume that traders from outside Maya lands were uninterested in acquiring resources produced by the Maya. Even if the Maya actually did produce only a small array of resources throughout their lands, there is no reason to believe from the text that people outside Maya lands also produced these same resources and thus would have no need to trade with the Maya people. Choice B is incorrect because the text indicates that scholars underestimated the ecological diversity of the Maya lands, which suggests that they mistakenly believed that the Maya produced a relatively small array of resources throughout their territory, not that the crops the Maya produced varied significantly throughout the Maya lands. Although the scholars might have assumed that a lack of ecological diversity suggests that Maya farming practices were largely the same everywhere, the text does not support that they also assumed there was a lot of variation in the crops that Maya people produced. In fact, the text states that marketplaces emerge when people want to obtain resources they don&rsquo;t already control. If it were the case that scholars assumed that the crops Maya people produced varied significantly, this would have led them to conclude that Maya people likely established marketplaces so they could trade for resources they didn&rsquo;t already possess, not that the Maya civilization lacked marketplaces. Choice D is incorrect because nothing in the text suggests that scholars assumed that farmers wouldn&rsquo;t trade their agricultural products unless they had already met their own needs with those products. Instead, the text says that scholars thought that the Maya lands produced a smaller array of resources than they actually did, which the text suggests led scholars to assume that the Maya didn&rsquo;t have any need for marketplaces. The scholars&rsquo; mistaken belief has no bearing on the issue of whether farmers met their own needs before trading their products. </p>","parenttemplatename":"OSP-049-INF","parenttemplateid":"","templateclusterid":"ba9b0527-7faa-4f01-a59c-94782261b9ed","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959323,"updateDate":1691007959323}$SATQ$::jsonb, 1691007959323, 1691007959323),
    ($SATQ$493c46bc$SATQ$, $SATQ$e84acee5-3f82-4072-a45f-7dc22a8038b2$SATQ$::uuid, $SATQ$491b9c30-6f53-4ffc-b254-5665ed8b2efa$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>In the South Pacific, New Caledonian crows use two different kinds of stick tools. One tool is complex. The crows shape a stick from a rare plant into a hook. The other tool is basic. The crows find a stick without a hook on the ground. The hooked tool is harder to get but is much better than the basic tool at removing prey from holes. When studying New Caledonian crows, ecologist Barbara Klump found that they hold the hooked tools in their claws when not using them, or they carefully put them in a safe place. The crows don&rsquo;t do the same with the basic tools. This suggests to Klump that the <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"569cfedf-fec4-4287-ad87-6aec6786c05e","content":"<p>hooked stick tools are more valuable to the crows than the stick tools without hooks.</p>"},{"id":"2c88f48b-362a-4d7f-bd65-c8533c5a525d","content":"<p>hooked stick tools are easier for most of the crows to hold than the stick tools without hooks.</p>"},{"id":"83f3052b-664a-4a6c-97f0-bc8ba298b83c","content":"<p>crows prefer to share their hooked stick tools but don&rsquo;t share the stick tools without hooks.</p>"},{"id":"a45d0f0e-1382-429f-9eb4-b4993f648a06","content":"<p>crows realize that both kinds of stick tools are less effective than their claws are at removing prey from holes.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["569cfedf-fec4-4287-ad87-6aec6786c05e"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of the two types of stick tools used by New Caledonian crows. The text indicates that the more effective type of tool has a hook that the crows make themselves, while the other type of tool is simply a stick without a hook that the crows find and don&rsquo;t shape in any way. According to the text, Klump found that the crows keep hooked tools&mdash;but not the tools without hooks&mdash;in their grasp or in safe places when they aren&rsquo;t using the tools. If the hooked tools are more effective than the tools without hooks are and the crows are more protective of the hooked tools than they are of the tools without hooks, it&rsquo;s reasonable to conclude that the hooked tools are more valuable to the crows than the tools without hooks are. </p><p>Choice B is incorrect because the text gives no indication of how easy it is for the crows to hold either the hooked tools or the tools without hooks. The text does state that crows hold the hooked tools and not the tools without hooks when the tools aren&rsquo;t in use. However, the text also indicates that the hooked tools require work from the crows to make and are more useful for helping the crows catch prey than the tools without hooks are. This context suggests that the crows hold the hooked tools because they&rsquo;re more valuable to the crows than the tools without hooks are, not because the hooked tools are easier to hold. Choice C is incorrect because the text makes no mention of the crows sharing tools. Additionally, the text indicates that when the crows aren&rsquo;t using the hooked tools, they either grasp the tools or store them safely, which suggests that the crows try to maintain possession of the hooked tools, not that crows prefer to share those tools. Choice D is incorrect because the text says nothing about the crows using their claws to remove prey from holes, so there&rsquo;s no evidence that the crows perceive the stick tools to be less effective than their claws are. </p>$SATQ$, false, 0, $SATQ$OSP-042-INF$SATQ$, $SATQ$$SATQ$, $SATQ$5292cf1b-d866-48c9-b086-a180930e25c8$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"493c46bc","external_id":"e84acee5-3f82-4072-a45f-7dc22a8038b2","vaultid":"491b9c30-6f53-4ffc-b254-5665ed8b2efa","uId":"b3d82723-6efa-4727-8c91-d01caf1a1993","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>In the South Pacific, New Caledonian crows use two different kinds of stick tools. One tool is complex. The crows shape a stick from a rare plant into a hook. The other tool is basic. The crows find a stick without a hook on the ground. The hooked tool is harder to get but is much better than the basic tool at removing prey from holes. When studying New Caledonian crows, ecologist Barbara Klump found that they hold the hooked tools in their claws when not using them, or they carefully put them in a safe place. The crows don&rsquo;t do the same with the basic tools. This suggests to Klump that the <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"569cfedf-fec4-4287-ad87-6aec6786c05e","content":"<p>hooked stick tools are more valuable to the crows than the stick tools without hooks.</p>"},{"id":"2c88f48b-362a-4d7f-bd65-c8533c5a525d","content":"<p>hooked stick tools are easier for most of the crows to hold than the stick tools without hooks.</p>"},{"id":"83f3052b-664a-4a6c-97f0-bc8ba298b83c","content":"<p>crows prefer to share their hooked stick tools but don&rsquo;t share the stick tools without hooks.</p>"},{"id":"a45d0f0e-1382-429f-9eb4-b4993f648a06","content":"<p>crows realize that both kinds of stick tools are less effective than their claws are at removing prey from holes.</p>"}],"keys":["569cfedf-fec4-4287-ad87-6aec6786c05e"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of the two types of stick tools used by New Caledonian crows. The text indicates that the more effective type of tool has a hook that the crows make themselves, while the other type of tool is simply a stick without a hook that the crows find and don&rsquo;t shape in any way. According to the text, Klump found that the crows keep hooked tools&mdash;but not the tools without hooks&mdash;in their grasp or in safe places when they aren&rsquo;t using the tools. If the hooked tools are more effective than the tools without hooks are and the crows are more protective of the hooked tools than they are of the tools without hooks, it&rsquo;s reasonable to conclude that the hooked tools are more valuable to the crows than the tools without hooks are. </p><p>Choice B is incorrect because the text gives no indication of how easy it is for the crows to hold either the hooked tools or the tools without hooks. The text does state that crows hold the hooked tools and not the tools without hooks when the tools aren&rsquo;t in use. However, the text also indicates that the hooked tools require work from the crows to make and are more useful for helping the crows catch prey than the tools without hooks are. This context suggests that the crows hold the hooked tools because they&rsquo;re more valuable to the crows than the tools without hooks are, not because the hooked tools are easier to hold. Choice C is incorrect because the text makes no mention of the crows sharing tools. Additionally, the text indicates that when the crows aren&rsquo;t using the hooked tools, they either grasp the tools or store them safely, which suggests that the crows try to maintain possession of the hooked tools, not that crows prefer to share those tools. Choice D is incorrect because the text says nothing about the crows using their claws to remove prey from holes, so there&rsquo;s no evidence that the crows perceive the stick tools to be less effective than their claws are. </p>","parenttemplatename":"OSP-042-INF","parenttemplateid":"","templateclusterid":"5292cf1b-d866-48c9-b086-a180930e25c8","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959322,"updateDate":1691007959322}$SATQ$::jsonb, 1691007959322, 1691007959322),
    ($SATQ$4987f743$SATQ$, $SATQ$217d6208-9618-4749-b9af-b89fbf69da88$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>ALSOL is a microcredit program in Mexico that makes small loans to female entrepreneurs who lack the collateral and credit history to secure financing from conventional banks. Borrowers use their business proceeds to repay loans in equal weekly installments and incur no penalty for missed payments other than lack of access to larger loans. Economists Gustavo Barboza and Sandra Trejos analyzed ALSOL data and found that rural borrowers, who mostly make and sell handicrafts, miss payments more often than urban borrowers do, partly because they sell their goods less frequently than they could. Barboza and Trejos claim that this behavior reflects strategic decisions that enable rural women to increase their profits per unit sold.</p>$SATQ$, $SATQ$<p>Which finding, if true, would most directly support Barboza and Trejos&rsquo;s claim?</p>$SATQ$, $SATQ$[{"id":"bc0588ac-e6ac-47f9-a760-9c8341de2f3f","content":"<p>Many marketplaces require entrepreneurs to pay marketplace operators a fixed percentage of each day&rsquo;s proceeds in exchange for permission to sell goods there.</p>"},{"id":"9eab1bd1-563d-40cd-a183-3dad1ec665d5","content":"<p>Rural entrepreneurs can typically sell their goods for higher prices in cities than in their home areas, but the number of people selling competing goods tends to be higher in cities.</p>"},{"id":"d7aa70e5-bebd-4021-aa00-d71f7e036ccd","content":"<p>Due to the lower costs they incur, rural entrepreneurs tend to require smaller initial loans than urban entrepreneurs do.&nbsp;</p>"},{"id":"24852524-49da-4604-b05c-50ce2b4f3635","content":"<p>The cost to rural entrepreneurs to bring their goods to towns with marketplaces is high but largely independent of the number of goods they bring.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["24852524-49da-4604-b05c-50ce2b4f3635"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it presents a finding that, if true, would most directly support Barboza and Trejos&rsquo;s claim that rural female entrepreneurs who have received small loans from ALSOL are strategic in selling their goods less frequently than they could, even if it means missing payments. The text explains that borrowers in the ALSOL program use proceeds from their businesses to repay loans in equal weekly payments, with almost no penalty for missed payments. According to the text, Barboza and Trejos found that rural borrowers miss weekly payments in part because they don&rsquo;t sell their goods as often as they could, a move the researchers claim allows the entrepreneurs to help increase profits for the goods they sell. Finding that the cost of bringing goods to towns with marketplaces is high for rural entrepreneurs but is largely independent of how many goods are brought would support the researchers&rsquo; claim: traveling to marketplaces less frequently would mean that a rural entrepreneur spends less on travel overall, and taking a large load of goods to a marketplace for essentially the same cost as taking a small load would allow the entrepreneur to more substantially offset the cost of travel with greater overall sales at the marketplace, resulting in more profit per good sold&mdash;even if those profits are earned less frequently and don&rsquo;t support weekly loan payments.</p><p>Choice A is incorrect because the finding that many marketplaces require entrepreneurs to pay the operators of the marketplace a fixed percentage of proceeds to be able to sell goods there wouldn&rsquo;t explain why rural entrepreneurs strategically choose to sell their goods less frequently than they could in order to increase their profits per unit sold. With a fixed percentage of proceeds due to operators, the amount entrepreneurs have to pay operators would also be fixed regardless of frequency of selling. Choice B is incorrect because the finding that rural entrepreneurs can usually sell their goods for higher prices in cities than in their local areas but also face higher competition to sell goods in cities wouldn&rsquo;t explain why rural entrepreneurs strategically choose to sell their goods less frequently than they could in order to increase their profits per unit sold. This is because both the higher prices and higher competition in cities would be stable factors&mdash;meaning there would be no clear reason for the rural entrepreneurs not to take every available chance to sell their goods in cities and to instead sell their goods in cities only sometimes. Choice C is incorrect because the finding that rural entrepreneurs have lower costs and thus tend to require smaller initial loans than urban entrepreneurs do has no bearing on rural borrowers strategically choosing to sell their goods less frequently than they could specifically to increase their profits per unit sold. The cost of producing goods doesn&rsquo;t depend on the frequency with which an entrepreneur sells those goods, so lower frequency alone wouldn&rsquo;t affect profits, and the initial loan amount is set and has nothing to do with how much profit is earned from each sale.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"4987f743","external_id":"217d6208-9618-4749-b9af-b89fbf69da88","vaultid":null,"uId":"f9963743-2e43-4af2-9b93-2997301b692f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>ALSOL is a microcredit program in Mexico that makes small loans to female entrepreneurs who lack the collateral and credit history to secure financing from conventional banks. Borrowers use their business proceeds to repay loans in equal weekly installments and incur no penalty for missed payments other than lack of access to larger loans. Economists Gustavo Barboza and Sandra Trejos analyzed ALSOL data and found that rural borrowers, who mostly make and sell handicrafts, miss payments more often than urban borrowers do, partly because they sell their goods less frequently than they could. Barboza and Trejos claim that this behavior reflects strategic decisions that enable rural women to increase their profits per unit sold.</p>","stem":"<p>Which finding, if true, would most directly support Barboza and Trejos&rsquo;s claim?</p>","answerOptions":[{"id":"bc0588ac-e6ac-47f9-a760-9c8341de2f3f","content":"<p>Many marketplaces require entrepreneurs to pay marketplace operators a fixed percentage of each day&rsquo;s proceeds in exchange for permission to sell goods there.</p>"},{"id":"9eab1bd1-563d-40cd-a183-3dad1ec665d5","content":"<p>Rural entrepreneurs can typically sell their goods for higher prices in cities than in their home areas, but the number of people selling competing goods tends to be higher in cities.</p>"},{"id":"d7aa70e5-bebd-4021-aa00-d71f7e036ccd","content":"<p>Due to the lower costs they incur, rural entrepreneurs tend to require smaller initial loans than urban entrepreneurs do.&nbsp;</p>"},{"id":"24852524-49da-4604-b05c-50ce2b4f3635","content":"<p>The cost to rural entrepreneurs to bring their goods to towns with marketplaces is high but largely independent of the number of goods they bring.&nbsp;</p>"}],"keys":["24852524-49da-4604-b05c-50ce2b4f3635"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it presents a finding that, if true, would most directly support Barboza and Trejos&rsquo;s claim that rural female entrepreneurs who have received small loans from ALSOL are strategic in selling their goods less frequently than they could, even if it means missing payments. The text explains that borrowers in the ALSOL program use proceeds from their businesses to repay loans in equal weekly payments, with almost no penalty for missed payments. According to the text, Barboza and Trejos found that rural borrowers miss weekly payments in part because they don&rsquo;t sell their goods as often as they could, a move the researchers claim allows the entrepreneurs to help increase profits for the goods they sell. Finding that the cost of bringing goods to towns with marketplaces is high for rural entrepreneurs but is largely independent of how many goods are brought would support the researchers&rsquo; claim: traveling to marketplaces less frequently would mean that a rural entrepreneur spends less on travel overall, and taking a large load of goods to a marketplace for essentially the same cost as taking a small load would allow the entrepreneur to more substantially offset the cost of travel with greater overall sales at the marketplace, resulting in more profit per good sold&mdash;even if those profits are earned less frequently and don&rsquo;t support weekly loan payments.</p><p>Choice A is incorrect because the finding that many marketplaces require entrepreneurs to pay the operators of the marketplace a fixed percentage of proceeds to be able to sell goods there wouldn&rsquo;t explain why rural entrepreneurs strategically choose to sell their goods less frequently than they could in order to increase their profits per unit sold. With a fixed percentage of proceeds due to operators, the amount entrepreneurs have to pay operators would also be fixed regardless of frequency of selling. Choice B is incorrect because the finding that rural entrepreneurs can usually sell their goods for higher prices in cities than in their local areas but also face higher competition to sell goods in cities wouldn&rsquo;t explain why rural entrepreneurs strategically choose to sell their goods less frequently than they could in order to increase their profits per unit sold. This is because both the higher prices and higher competition in cities would be stable factors&mdash;meaning there would be no clear reason for the rural entrepreneurs not to take every available chance to sell their goods in cities and to instead sell their goods in cities only sometimes. Choice C is incorrect because the finding that rural entrepreneurs have lower costs and thus tend to require smaller initial loans than urban entrepreneurs do has no bearing on rural borrowers strategically choosing to sell their goods less frequently than they could specifically to increase their profits per unit sold. The cost of producing goods doesn&rsquo;t depend on the frequency with which an entrepreneur sells those goods, so lower frequency alone wouldn&rsquo;t affect profits, and the initial loan amount is set and has nothing to do with how much profit is earned from each sale.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669204,"updateDate":1743430669204}$SATQ$::jsonb, 1743430669204, 1743430669204),
    ($SATQ$4a07be59$SATQ$, $SATQ$047e7067-f570-44e5-8e44-a92ea3f8b3b9$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Neurobiologists Laura Cuaya, Ra&uacute;l Hern&aacute;ndez-P&eacute;rez, and colleagues investigated the language detection abilities of eighteen dogs. The researchers monitored the brain activity of Joey (an Australian shepherd), Mini (a mixed breed), and other dogs while the animals listened to three recordings: one of&nbsp;<em>The Little Prince</em> being read in Spanish, the second in Hungarian, and a third made up of short, randomly selected fragments of the first two, scrambled so that they didn&rsquo;t resemble human speech. Each dog was familiar with either Spanish or Hungarian, but not both. The team concluded that differences in dogs&rsquo; anatomical features may affect their ability to distinguish speech from nonspeech.</p>$SATQ$, $SATQ$<p>Which finding from the study, if true, would most directly support the team&rsquo;s conclusion?</p>$SATQ$, $SATQ$[{"id":"f4517b05-421b-4960-9800-0af27c8d8ed1","content":"<p>Long-headed dogs accustomed to hearing Spanish tended to show more brain activity when hearing Spanish than long-headed dogs accustomed to hearing Hungarian showed when hearing Hungarian.&nbsp;</p>"},{"id":"0998b970-b13a-4d2e-bf02-c78588267875","content":"<p>Compared with shorter-headed dogs, longer-headed dogs showed a greater difference in brain activity when hearing either Spanish or Hungarian than when hearing the scrambled recording.</p>"},{"id":"cb486208-8dd7-43a6-b834-2fd61508b85a","content":"<p>The pattern of brain activity that long-headed dogs showed when hearing the scrambled recording was different from the pattern of brain activity that short-headed dogs showed when hearing the language they were accustomed to.&nbsp;</p>"},{"id":"f8ddb237-e762-494c-95ba-0bb13b25831d","content":"<p>Compared with shorter-headed dogs, longer-headed dogs showed a greater difference in brain activity when hearing the language they were accustomed to than when hearing the other language.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["0998b970-b13a-4d2e-bf02-c78588267875"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it presents a finding that, if true, would most directly support the research team&rsquo;s conclusion about anatomical features and speech detection in dogs. The text explains that a team of researchers monitored the brain activity of dogs while the dogs listened to three recordings: one of spoken Spanish, one of spoken Hungarian, and one of scrambled fragments that weren&rsquo;t recognizable as human speech. The text then states that the team concluded that differences in dogs&rsquo; anatomical features may affect their ability to distinguish speech from nonspeech. The finding that longer-headed dogs exhibited a greater difference in brain activity when listening to the speech recordings (in Spanish or Hungarian) versus the nonspeech (scrambled) recording compared with shorter-headed dogs would establish an association between an anatomical feature (head length) and responses (as measured by brain activity) to speech versus nonspeech. This observed relationship between head length and brain activity patterns during exposure to speech and nonspeech would support the team&rsquo;s conclusion.</p><p>Choice A is incorrect because it describes a finding about dogs&rsquo; responses (as indicated by brain activity) to hearing their respective familiar languages rather than dogs&rsquo; ability to distinguish speech from nonspeech, which is what the team&rsquo;s conclusion specifically addresses. Moreover, this finding pertains to only one anatomical type (long-headed dogs), so it wouldn&rsquo;t support the conclusion that anatomical differences may affect dogs&rsquo; ability to distinguish speech from nonspeech. Choice C is incorrect because it describes a finding involving a comparison between long-headed dogs listening to nonspeech and short-headed dogs listening to speech, which wouldn&rsquo;t provide enough information to support the researchers&rsquo; conclusion that anatomical differences may affect dogs&rsquo; ability to distinguish speech from nonspeech. To support that conclusion, the finding would need to show how dogs with different anatomical features (for example, long-headed and short-headed dogs) respond to recordings of speech as well as recordings of nonspeech. Choice D is incorrect because it describes a finding about dogs&rsquo; ability to distinguish between a familiar language and an unfamiliar one, not between speech and nonspeech. While this finding does compare dogs with different anatomical features (longer-headed vs. shorter-headed ones), it focuses on language recognition (Spanish vs. Hungarian) rather than the ability to distinguish speech from nonspeech, which is what the team&rsquo;s conclusion specifically addresses.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"4a07be59","external_id":"047e7067-f570-44e5-8e44-a92ea3f8b3b9","vaultid":null,"uId":"84c6dbba-10e9-45ba-bd18-6873fbd20f5a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Neurobiologists Laura Cuaya, Ra&uacute;l Hern&aacute;ndez-P&eacute;rez, and colleagues investigated the language detection abilities of eighteen dogs. The researchers monitored the brain activity of Joey (an Australian shepherd), Mini (a mixed breed), and other dogs while the animals listened to three recordings: one of&nbsp;<em>The Little Prince</em> being read in Spanish, the second in Hungarian, and a third made up of short, randomly selected fragments of the first two, scrambled so that they didn&rsquo;t resemble human speech. Each dog was familiar with either Spanish or Hungarian, but not both. The team concluded that differences in dogs&rsquo; anatomical features may affect their ability to distinguish speech from nonspeech.</p>","stem":"<p>Which finding from the study, if true, would most directly support the team&rsquo;s conclusion?</p>","answerOptions":[{"id":"f4517b05-421b-4960-9800-0af27c8d8ed1","content":"<p>Long-headed dogs accustomed to hearing Spanish tended to show more brain activity when hearing Spanish than long-headed dogs accustomed to hearing Hungarian showed when hearing Hungarian.&nbsp;</p>"},{"id":"0998b970-b13a-4d2e-bf02-c78588267875","content":"<p>Compared with shorter-headed dogs, longer-headed dogs showed a greater difference in brain activity when hearing either Spanish or Hungarian than when hearing the scrambled recording.</p>"},{"id":"cb486208-8dd7-43a6-b834-2fd61508b85a","content":"<p>The pattern of brain activity that long-headed dogs showed when hearing the scrambled recording was different from the pattern of brain activity that short-headed dogs showed when hearing the language they were accustomed to.&nbsp;</p>"},{"id":"f8ddb237-e762-494c-95ba-0bb13b25831d","content":"<p>Compared with shorter-headed dogs, longer-headed dogs showed a greater difference in brain activity when hearing the language they were accustomed to than when hearing the other language.</p>"}],"keys":["0998b970-b13a-4d2e-bf02-c78588267875"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it presents a finding that, if true, would most directly support the research team&rsquo;s conclusion about anatomical features and speech detection in dogs. The text explains that a team of researchers monitored the brain activity of dogs while the dogs listened to three recordings: one of spoken Spanish, one of spoken Hungarian, and one of scrambled fragments that weren&rsquo;t recognizable as human speech. The text then states that the team concluded that differences in dogs&rsquo; anatomical features may affect their ability to distinguish speech from nonspeech. The finding that longer-headed dogs exhibited a greater difference in brain activity when listening to the speech recordings (in Spanish or Hungarian) versus the nonspeech (scrambled) recording compared with shorter-headed dogs would establish an association between an anatomical feature (head length) and responses (as measured by brain activity) to speech versus nonspeech. This observed relationship between head length and brain activity patterns during exposure to speech and nonspeech would support the team&rsquo;s conclusion.</p><p>Choice A is incorrect because it describes a finding about dogs&rsquo; responses (as indicated by brain activity) to hearing their respective familiar languages rather than dogs&rsquo; ability to distinguish speech from nonspeech, which is what the team&rsquo;s conclusion specifically addresses. Moreover, this finding pertains to only one anatomical type (long-headed dogs), so it wouldn&rsquo;t support the conclusion that anatomical differences may affect dogs&rsquo; ability to distinguish speech from nonspeech. Choice C is incorrect because it describes a finding involving a comparison between long-headed dogs listening to nonspeech and short-headed dogs listening to speech, which wouldn&rsquo;t provide enough information to support the researchers&rsquo; conclusion that anatomical differences may affect dogs&rsquo; ability to distinguish speech from nonspeech. To support that conclusion, the finding would need to show how dogs with different anatomical features (for example, long-headed and short-headed dogs) respond to recordings of speech as well as recordings of nonspeech. Choice D is incorrect because it describes a finding about dogs&rsquo; ability to distinguish between a familiar language and an unfamiliar one, not between speech and nonspeech. While this finding does compare dogs with different anatomical features (longer-headed vs. shorter-headed ones), it focuses on language recognition (Spanish vs. Hungarian) rather than the ability to distinguish speech from nonspeech, which is what the team&rsquo;s conclusion specifically addresses.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061175,"updateDate":1755117061175}$SATQ$::jsonb, 1755117061175, 1755117061175),
    ($SATQ$4a85fea6$SATQ$, $SATQ$6d69ca0b-7396-4810-a1bf-106bf87f045a$SATQ$::uuid, $SATQ$fa7b8f89-523b-4a74-984c-5a5aa2c933e9$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p><em>Euphorbia esula</em> (leafy spurge) is a Eurasian plant that has become invasive in North America, where it displaces native vegetation and sickens cattle. <em>E. esula</em> can be controlled with chemical herbicides, but that approach can also kill harmless plants nearby. Recent research on introducing engineered DNA into plant species to inhibit their reproduction may offer a path toward exclusively targeting <em>E. esula</em>, consequently <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"2b9c7657-7ab7-4b3b-94b8-f7b09815a496","content":"<p>making individual <em>E. esula</em> plants more susceptible to existing chemical herbicides.</p>"},{"id":"9e4a0298-4daf-46be-bd7e-4a4174cee624","content":"<p>enhancing the ecological benefits of <em>E. esula</em> in North America.</p>"},{"id":"4dd1b85d-7bd4-4461-8abc-50518e2804e9","content":"<p>enabling cattle to consume <em>E. esula&nbsp;</em>without becoming sick.</p>"},{"id":"6752f11a-8fde-4cad-9a3d-e7f900365237","content":"<p>reducing invasive <em>E. esula</em> numbers without harming other organisms.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["6752f11a-8fde-4cad-9a3d-e7f900365237"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it presents the conclusion that most logically follows from the text&rsquo;s discussion of leafy spurge and engineered DNA. The text establishes that using chemical herbicides to control leafy spurge in North America can also harm other plants nearby. The text then indicates that it might be possible to use engineered DNA to prevent plants from reproducing, which would be useful for &ldquo;exclusively targeting&rdquo; leafy spurge. If it&rsquo;s possible to exclusively target leafy spurge with engineered DNA&mdash;meaning that only leafy spurge is affected by the engineered DNA&mdash;and prevent the plant from reproducing, then leafy spurge numbers could be reduced &ldquo;without harming other organisms.&rdquo; </p><p>Choice A is incorrect because the text raises the possibility of using engineered DNA to prevent leafy spurge from reproducing, not to make individual leafy spurge plants more vulnerable to chemical herbicides that already exist.&nbsp;Choice B is incorrect because the text doesn&rsquo;t describe any ecological benefits of leafy spurge in North America; instead, the text is focused on using engineered DNA to prevent leafy spurge from reproducing and thereby reduce its numbers. The only ecological effects of leafy spurge in North America that are described in the text are harmful.&nbsp;Choice C is incorrect because the text describes the possibility of using engineered DNA to prevent leafy spurge from reproducing; it doesn&rsquo;t offer a way to enable cattle to eat leafy spurge without becoming sick.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-001-INF$SATQ$, $SATQ$$SATQ$, $SATQ$5a876bfe-6622-49f9-8167-c332267f2e93$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"4a85fea6","external_id":"6d69ca0b-7396-4810-a1bf-106bf87f045a","vaultid":"fa7b8f89-523b-4a74-984c-5a5aa2c933e9","uId":"8a60982c-9f5c-48fa-9c05-342412a9e7e4","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p><em>Euphorbia esula</em> (leafy spurge) is a Eurasian plant that has become invasive in North America, where it displaces native vegetation and sickens cattle. <em>E. esula</em> can be controlled with chemical herbicides, but that approach can also kill harmless plants nearby. Recent research on introducing engineered DNA into plant species to inhibit their reproduction may offer a path toward exclusively targeting <em>E. esula</em>, consequently <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"2b9c7657-7ab7-4b3b-94b8-f7b09815a496","content":"<p>making individual <em>E. esula</em> plants more susceptible to existing chemical herbicides.</p>"},{"id":"9e4a0298-4daf-46be-bd7e-4a4174cee624","content":"<p>enhancing the ecological benefits of <em>E. esula</em> in North America.</p>"},{"id":"4dd1b85d-7bd4-4461-8abc-50518e2804e9","content":"<p>enabling cattle to consume <em>E. esula&nbsp;</em>without becoming sick.</p>"},{"id":"6752f11a-8fde-4cad-9a3d-e7f900365237","content":"<p>reducing invasive <em>E. esula</em> numbers without harming other organisms.</p>"}],"keys":["6752f11a-8fde-4cad-9a3d-e7f900365237"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it presents the conclusion that most logically follows from the text&rsquo;s discussion of leafy spurge and engineered DNA. The text establishes that using chemical herbicides to control leafy spurge in North America can also harm other plants nearby. The text then indicates that it might be possible to use engineered DNA to prevent plants from reproducing, which would be useful for &ldquo;exclusively targeting&rdquo; leafy spurge. If it&rsquo;s possible to exclusively target leafy spurge with engineered DNA&mdash;meaning that only leafy spurge is affected by the engineered DNA&mdash;and prevent the plant from reproducing, then leafy spurge numbers could be reduced &ldquo;without harming other organisms.&rdquo; </p><p>Choice A is incorrect because the text raises the possibility of using engineered DNA to prevent leafy spurge from reproducing, not to make individual leafy spurge plants more vulnerable to chemical herbicides that already exist.&nbsp;Choice B is incorrect because the text doesn&rsquo;t describe any ecological benefits of leafy spurge in North America; instead, the text is focused on using engineered DNA to prevent leafy spurge from reproducing and thereby reduce its numbers. The only ecological effects of leafy spurge in North America that are described in the text are harmful.&nbsp;Choice C is incorrect because the text describes the possibility of using engineered DNA to prevent leafy spurge from reproducing; it doesn&rsquo;t offer a way to enable cattle to eat leafy spurge without becoming sick.&nbsp;</p>","parenttemplatename":"OSP-001-INF","parenttemplateid":"","templateclusterid":"5a876bfe-6622-49f9-8167-c332267f2e93","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959311,"updateDate":1691007959311}$SATQ$::jsonb, 1691007959311, 1691007959311),
    ($SATQ$4b3d6062$SATQ$, $SATQ$6bc7928c-513a-4331-9eeb-9dc97afdf1c7$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>The <em>Mammillaria </em>cactus <em><span data-ssml-sub-alias="M">M.</span> boolii</em> occurs naturally only in the state of Sonora in Mexico, and the smallness of its range makes it especially vulnerable to extinction. The traditional single-species approach to conservation emphasizes the need to focus on individual species most at risk, like <em><span data-ssml-sub-alias="M">M.</span> boolii</em>, but recently, conservationists have argued that an ecosystem-based approach that incorporates the many interactions between the climate, terrain, and various species of a given geographical area may lead to better outcomes for all the species in a given location. If this view is correct, the single-species approach to the conservation of <em><span data-ssml-sub-alias="M">M.</span> boolii </em>could thus <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"d4eb39b3-ab40-44ec-aade-80016a72bbc9","content":"<p>lead to a better understanding of how the distribution of <em>Mammillaria</em> species throughout Mexico has affected their survival.</p>"},{"id":"4779c59b-c8fe-40b8-9b19-0462ecd3960d","content":"<p>allow conservationists to better consider how climatic changes affecting Sonora may reduce the number of species competing with <em><span data-ssml-sub-alias=\"M\">M.</span> boolii</em>.</p>"},{"id":"a37fcd9a-9a7e-4988-b97e-9d56fce7aa85","content":"<p>erroneously shift the focus of conservation efforts away from <em><span data-ssml-sub-alias=\"M\">M.</span> boolii</em> itself.</p>"},{"id":"cc9d9062-8656-4135-be39-c00477e9f740","content":"<p>fail to consider the ways in which the survival of <em><span data-ssml-sub-alias=\"M\">M.</span> boolii</em> may be influenced by changes in the populations of other species that inhabit Sonora.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["cc9d9062-8656-4135-be39-c00477e9f740"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of conservation approaches for the <em>Mammillaria </em>cactus <em>M. boolii</em>. The text establishes that <em>M. boolii</em> only grows naturally in the state of Sonora in Mexico, which makes it particularly vulnerable to extinction. The text then contrasts two approaches to conservation: the traditional single-species approach that individually focuses on at-risk species and a newer ecosystem-based approach that considers the interactions between climate, terrain, and various species in a geographical area. According to the text, conservationists have recently argued that this ecosystem-based approach may lead to better outcomes for all species in a location. If this ecosystem view is correct, then the single-species approach to conserving <em><span data-ssml-sub-alias="M">M.</span> boolii</em> would likely fail to consider how the cactus&rsquo;s survival depends on its interactions with other species in Sonora&rsquo;s ecosystem.</p><p>Choice A is incorrect because  the text doesn&rsquo;t address the distribution of <em>Mammillaria </em>species besides <em>M. boolii</em> throughout Mexico or discuss how that distribution affects survival. The text focuses specifically on <em>M. boolii</em> in Sonora and different approaches to its conservation. Choice B is incorrect because the text doesn&rsquo;t suggest that climatic changes in Sonora would reduce competition for <em>M. boolii</em> or that conservation efforts are focused on understanding this specific dynamic. In fact, the text implies that an ecosystem-based approach would consider climate among many other factors but doesn&rsquo;t specify how climatic changes might affect competition between species. Choice C is incorrect because the text doesn&rsquo;t suggest that the single-species approach would shift the focus of conservation efforts away from <em>M. boolii</em> itself&mdash;rather, it suggests that this approach might be too narrowly focused on <em>M. boolii</em> alone without considering the broader ecosystem-related factors that affect its survival.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"4b3d6062","external_id":"6bc7928c-513a-4331-9eeb-9dc97afdf1c7","vaultid":null,"uId":"13d8ab0b-7367-49d8-a22b-dddea8bab58d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>The <em>Mammillaria </em>cactus <em><span data-ssml-sub-alias=\"M\">M.</span> boolii</em> occurs naturally only in the state of Sonora in Mexico, and the smallness of its range makes it especially vulnerable to extinction. The traditional single-species approach to conservation emphasizes the need to focus on individual species most at risk, like <em><span data-ssml-sub-alias=\"M\">M.</span> boolii</em>, but recently, conservationists have argued that an ecosystem-based approach that incorporates the many interactions between the climate, terrain, and various species of a given geographical area may lead to better outcomes for all the species in a given location. If this view is correct, the single-species approach to the conservation of <em><span data-ssml-sub-alias=\"M\">M.</span> boolii </em>could thus <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"d4eb39b3-ab40-44ec-aade-80016a72bbc9","content":"<p>lead to a better understanding of how the distribution of <em>Mammillaria</em> species throughout Mexico has affected their survival.</p>"},{"id":"4779c59b-c8fe-40b8-9b19-0462ecd3960d","content":"<p>allow conservationists to better consider how climatic changes affecting Sonora may reduce the number of species competing with <em><span data-ssml-sub-alias=\"M\">M.</span> boolii</em>.</p>"},{"id":"a37fcd9a-9a7e-4988-b97e-9d56fce7aa85","content":"<p>erroneously shift the focus of conservation efforts away from <em><span data-ssml-sub-alias=\"M\">M.</span> boolii</em> itself.</p>"},{"id":"cc9d9062-8656-4135-be39-c00477e9f740","content":"<p>fail to consider the ways in which the survival of <em><span data-ssml-sub-alias=\"M\">M.</span> boolii</em> may be influenced by changes in the populations of other species that inhabit Sonora.</p>"}],"keys":["cc9d9062-8656-4135-be39-c00477e9f740"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of conservation approaches for the <em>Mammillaria </em>cactus <em>M. boolii</em>. The text establishes that <em>M. boolii</em> only grows naturally in the state of Sonora in Mexico, which makes it particularly vulnerable to extinction. The text then contrasts two approaches to conservation: the traditional single-species approach that individually focuses on at-risk species and a newer ecosystem-based approach that considers the interactions between climate, terrain, and various species in a geographical area. According to the text, conservationists have recently argued that this ecosystem-based approach may lead to better outcomes for all species in a location. If this ecosystem view is correct, then the single-species approach to conserving <em><span data-ssml-sub-alias=\"M\">M.</span> boolii</em> would likely fail to consider how the cactus&rsquo;s survival depends on its interactions with other species in Sonora&rsquo;s ecosystem.</p><p>Choice A is incorrect because  the text doesn&rsquo;t address the distribution of <em>Mammillaria </em>species besides <em>M. boolii</em> throughout Mexico or discuss how that distribution affects survival. The text focuses specifically on <em>M. boolii</em> in Sonora and different approaches to its conservation. Choice B is incorrect because the text doesn&rsquo;t suggest that climatic changes in Sonora would reduce competition for <em>M. boolii</em> or that conservation efforts are focused on understanding this specific dynamic. In fact, the text implies that an ecosystem-based approach would consider climate among many other factors but doesn&rsquo;t specify how climatic changes might affect competition between species. Choice C is incorrect because the text doesn&rsquo;t suggest that the single-species approach would shift the focus of conservation efforts away from <em>M. boolii</em> itself&mdash;rather, it suggests that this approach might be too narrowly focused on <em>M. boolii</em> alone without considering the broader ecosystem-related factors that affect its survival.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061178,"updateDate":1755117061178}$SATQ$::jsonb, 1755117061178, 1755117061178),
    ($SATQ$4b8eda0a$SATQ$, $SATQ$803cff0c-4ba0-4ec3-b690-1fe2486e401e$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>For its 1974 work <em>Instant Mural</em>, the Chicano art collective Asco taped members Patssi Valdez and Humberto Sandoval to an outdoor wall in East Los Angeles. The work is manifestly a commentary on constraint, but many critics focus on Valdez and the social constraints women faced at the time, which is understandable but leaves the presence of Valdez&rsquo;s male collaborator Sandoval unexplained. We should instead consider that in 1974, the art establishment&rsquo;s recognition of Chicano artists was (and had long been) restricted to sociohistorical muralists, leaving nonmuralist Chicano artists&mdash;like Asco&rsquo;s members&mdash;struggling to even exhibit their work; attending to this context opens an interpretation that accounts for all the evidence, allowing us to conclude that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"d0427043-06e6-47a7-924a-4c48810d66ba","content":"<p>while Valdez&rsquo;s presence in <em>Instant Mural</em> represents the social constraints placed on women at the time, Sandoval&rsquo;s presence represents Chicano muralists&rsquo; frustration at their lack of recognition by the art establishment.</p>"},{"id":"476fd933-38e4-437e-b4ad-916a744afe36","content":"<p>the main subject of <em>Instant Mural</em> is female Chicano artists&rsquo; experience of being doubly constrained by gender-role expectations and the marginalization of certain types of art.</p>"},{"id":"6f274bf1-efea-42fc-98cf-781b88508d6b","content":"<p><em>Instant Mural</em> is a reflection on the constraining aesthetic expectations placed on Chicano artists in general rather than on the social constraints placed on women specifically.</p>"},{"id":"3b508791-c1bf-4d53-89f3-307571295e93","content":"<p><em>Instant Mural</em> is best understood not as a critique of the social constraints placed on women but rather as a critique of sociohistorical muralists&rsquo; depictions of Chicano culture.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["6f274bf1-efea-42fc-98cf-781b88508d6b"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of <em>Instant Mural</em>. According to the text, the 1974 work <em>Instant Mural</em> involved taping two Asco members (Patssi Valdez and Humberto Sandoval) to an outdoor wall as a direct commentary on constraint (limitation or restriction). The text suggests that instead of focusing on Valdez&rsquo;s role in the work and on social limitations women faced at the time&mdash;an approach that fails to explain the role of Sandoval, a man&mdash;people should consider that in 1974 (and long before) the art establishment limited recognition of Chicano artists to those who created murals with social and historical subjects, making it challenging for nonmuralist Chicano artists (such as Asco&rsquo;s members) to show their work. The text suggests that considering the situation with the art establishment leads to a conclusion that accounts for the fact that <em>Instant Mural</em> is explicitly about constraint and features both a woman and a man taped to the wall: <em>Instant Mural</em> isn&rsquo;t a reflection of the social constraints placed on women specifically but instead is a reflection on the constraining aesthetic expectations placed on Chicano artists in general (that is, the limits resulting from the lack of recognition of Chicano artists of any gender who did not create sociohistorical murals).</p><p>Choice A is incorrect. The text indicates that the art establishment in 1974 (and earlier) did recognize Chicano muralists to the exclusion of other Chicano artists, so there&rsquo;s no reason to assume Asco&rsquo;s work <em>Instant Mural</em> was intended to represent Chicano muralists&rsquo; frustration; it&rsquo;s far more likely that Asco&rsquo;s members&mdash;described as Chicano nonmuralists&mdash;were representing their own frustration at being unrecognized by the art establishment. Choice B is incorrect. The text emphasizes that while a common approach to <em>Instant Mural</em> focuses on Valdez and the social limitations women faced in 1974 but fails to account for the presence of a man in the work, there is a conclusion that explains Sandoval&rsquo;s role. But concluding that <em>Instant Mural</em> represents a double constraint experienced specifically by female Chicano artists would still fail to account for the inclusion of a man in the work. Choice D is incorrect. Although the text suggests that <em>Instant Mural</em> can be understood as something other than a commentary on social constraints women faced in 1974, it doesn&rsquo;t suggest that the work is best understood as a critique of the content of any other artworks. The text doesn&rsquo;t address how Chicano culture is depicted in sociohistorical murals; it discusses such murals only to make the point that in 1974 (and earlier) the art establishment recognized Chicano artists who produced them to the exclusion of Chicano nonmuralists, indicating a constraint all of Asco&rsquo;s members faced, regardless of gender.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"4b8eda0a","external_id":"803cff0c-4ba0-4ec3-b690-1fe2486e401e","vaultid":null,"uId":"599fad90-1e71-4ccf-bb33-180689a9aabe","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>For its 1974 work <em>Instant Mural</em>, the Chicano art collective Asco taped members Patssi Valdez and Humberto Sandoval to an outdoor wall in East Los Angeles. The work is manifestly a commentary on constraint, but many critics focus on Valdez and the social constraints women faced at the time, which is understandable but leaves the presence of Valdez&rsquo;s male collaborator Sandoval unexplained. We should instead consider that in 1974, the art establishment&rsquo;s recognition of Chicano artists was (and had long been) restricted to sociohistorical muralists, leaving nonmuralist Chicano artists&mdash;like Asco&rsquo;s members&mdash;struggling to even exhibit their work; attending to this context opens an interpretation that accounts for all the evidence, allowing us to conclude that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"d0427043-06e6-47a7-924a-4c48810d66ba","content":"<p>while Valdez&rsquo;s presence in <em>Instant Mural</em> represents the social constraints placed on women at the time, Sandoval&rsquo;s presence represents Chicano muralists&rsquo; frustration at their lack of recognition by the art establishment.</p>"},{"id":"476fd933-38e4-437e-b4ad-916a744afe36","content":"<p>the main subject of <em>Instant Mural</em> is female Chicano artists&rsquo; experience of being doubly constrained by gender-role expectations and the marginalization of certain types of art.</p>"},{"id":"6f274bf1-efea-42fc-98cf-781b88508d6b","content":"<p><em>Instant Mural</em> is a reflection on the constraining aesthetic expectations placed on Chicano artists in general rather than on the social constraints placed on women specifically.</p>"},{"id":"3b508791-c1bf-4d53-89f3-307571295e93","content":"<p><em>Instant Mural</em> is best understood not as a critique of the social constraints placed on women but rather as a critique of sociohistorical muralists&rsquo; depictions of Chicano culture.</p>"}],"keys":["6f274bf1-efea-42fc-98cf-781b88508d6b"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of <em>Instant Mural</em>. According to the text, the 1974 work <em>Instant Mural</em> involved taping two Asco members (Patssi Valdez and Humberto Sandoval) to an outdoor wall as a direct commentary on constraint (limitation or restriction). The text suggests that instead of focusing on Valdez&rsquo;s role in the work and on social limitations women faced at the time&mdash;an approach that fails to explain the role of Sandoval, a man&mdash;people should consider that in 1974 (and long before) the art establishment limited recognition of Chicano artists to those who created murals with social and historical subjects, making it challenging for nonmuralist Chicano artists (such as Asco&rsquo;s members) to show their work. The text suggests that considering the situation with the art establishment leads to a conclusion that accounts for the fact that <em>Instant Mural</em> is explicitly about constraint and features both a woman and a man taped to the wall: <em>Instant Mural</em> isn&rsquo;t a reflection of the social constraints placed on women specifically but instead is a reflection on the constraining aesthetic expectations placed on Chicano artists in general (that is, the limits resulting from the lack of recognition of Chicano artists of any gender who did not create sociohistorical murals).</p><p>Choice A is incorrect. The text indicates that the art establishment in 1974 (and earlier) did recognize Chicano muralists to the exclusion of other Chicano artists, so there&rsquo;s no reason to assume Asco&rsquo;s work <em>Instant Mural</em> was intended to represent Chicano muralists&rsquo; frustration; it&rsquo;s far more likely that Asco&rsquo;s members&mdash;described as Chicano nonmuralists&mdash;were representing their own frustration at being unrecognized by the art establishment. Choice B is incorrect. The text emphasizes that while a common approach to <em>Instant Mural</em> focuses on Valdez and the social limitations women faced in 1974 but fails to account for the presence of a man in the work, there is a conclusion that explains Sandoval&rsquo;s role. But concluding that <em>Instant Mural</em> represents a double constraint experienced specifically by female Chicano artists would still fail to account for the inclusion of a man in the work. Choice D is incorrect. Although the text suggests that <em>Instant Mural</em> can be understood as something other than a commentary on social constraints women faced in 1974, it doesn&rsquo;t suggest that the work is best understood as a critique of the content of any other artworks. The text doesn&rsquo;t address how Chicano culture is depicted in sociohistorical murals; it discusses such murals only to make the point that in 1974 (and earlier) the art establishment recognized Chicano artists who produced them to the exclusion of Chicano nonmuralists, indicating a constraint all of Asco&rsquo;s members faced, regardless of gender.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669210,"updateDate":1743430669210}$SATQ$::jsonb, 1743430669210, 1743430669210),
    ($SATQ$4ba0695d$SATQ$, $SATQ$4ef4acdb-0900-4f53-b1b8-09f665f80d2c$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>The alpaca was domesticated by Indigenous peoples in the Andes about 7,000 years ago. But which wild species did it descend from, the vicu&ntilde;a or guanaco? A research team led by Ruiwen Fan may have solved the mystery, concluding that the alpaca is the domesticated form of the vicu&ntilde;a but that the modern alpaca gets only 64 percent of its genetic material from its wild ancestor. The rest comes from the domesticated llama. The llama, meanwhile, gets 95.5 percent of its genetic material from its own wild ancestor, the guanaco, and the rest from the alpaca. The llama and alpaca apparently interbred widely for only a handful of generations between 400 and 600 years ago. Assuming that the findings of Fan&rsquo;s team are valid, it can be inferred that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"6fa2b359-408b-4960-a1e5-4df1f73ac135","content":"<p>modern llama populations have a greater degree of genetic diversity, on average, than modern alpaca populations do.</p>"},{"id":"7256f215-0003-4df0-95c8-8e303e861d3f","content":"<p>the domestication process of the alpaca may have involved some introduction of genetic material from the llama.</p>"},{"id":"aa6fc7c7-2496-40b0-b318-97543da425a5","content":"<p>the period of interbreeding resulted in a greater genetic difference between alpacas and their wild ancestors than between llamas and their wild ancestors.</p>"},{"id":"d79fd1dc-f5d7-41f5-8e9b-f627102cf7b2","content":"<p>if they were subjected to genetic testing, modern populations of guanacos and vicu&ntilde;as would likely show traces of ancient interbreeding as well.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["aa6fc7c7-2496-40b0-b318-97543da425a5"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it presents the inference that most logically follows from the text&rsquo;s discussion of the genetic material of alpacas. The text states that modern alpacas get only 64 percent of their genetic material from their wild ancestor (the vicu&ntilde;a), while llamas get 95.5 percent of their genetic material from their wild ancestor (the guanaco). These data imply that relative to llamas, alpacas have experienced a much greater genetic shift away from their wild ancestors (36 percent of their genetic material derives from another source, compared to 4.5 percent of llamas&rsquo; genetic material). Moreover, the text establishes that the remainder of alpacas&rsquo; genetic material derives from llamas, and the remainder of llamas&rsquo; genetic material derives from alpacas, reflecting a period of interbreeding. Taken together, these details support the inference that the period of interbreeding had a more significant impact on the genetic material of alpacas than on that of llamas, thereby reducing the percentage of alpacas&rsquo; genetic material that derives from wild ancestors and placing alpacas at a greater remove from these ancestors.</p><p>Choice A is incorrect because the text doesn&rsquo;t provide information about genetic diversity within modern llama and alpaca populations. While the text discusses the percentage of genetic material each domesticated species inherited from its wild ancestor and from interbreeding, it does not address the level of genetic variation within each species. Therefore, it isn&rsquo;t logical to infer that modern llama populations have a greater degree of genetic diversity than modern alpaca populations do. Choice B is incorrect because it contradicts the chronology presented in the text. The text states that alpacas were domesticated about 7,000 years ago, but the interbreeding with llamas occurred "between 400 and 600 years ago." The genetic mixing happened thousands of years after domestication, not during it; in addition, the text does not provide details about what the process of domestication might entail. Therefore, it isn&rsquo;t logical to infer that llama genetic material was introduced during the domestication process of alpacas. Choice D is incorrect because though the text notes that guanacos and vicu&ntilde;as contributed to the genetic material of alpacas and llamas, it only discusses alpacas&rsquo; and llamas&rsquo; genetic composition. Therefore, the text does not support the inference that modern populations of guanacos and vicu&ntilde;as would likely show traces of ancient interbreeding.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"4ba0695d","external_id":"4ef4acdb-0900-4f53-b1b8-09f665f80d2c","vaultid":null,"uId":"430da439-c2b9-42a0-8eff-d79876558a35","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>The alpaca was domesticated by Indigenous peoples in the Andes about 7,000 years ago. But which wild species did it descend from, the vicu&ntilde;a or guanaco? A research team led by Ruiwen Fan may have solved the mystery, concluding that the alpaca is the domesticated form of the vicu&ntilde;a but that the modern alpaca gets only 64 percent of its genetic material from its wild ancestor. The rest comes from the domesticated llama. The llama, meanwhile, gets 95.5 percent of its genetic material from its own wild ancestor, the guanaco, and the rest from the alpaca. The llama and alpaca apparently interbred widely for only a handful of generations between 400 and 600 years ago. Assuming that the findings of Fan&rsquo;s team are valid, it can be inferred that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"6fa2b359-408b-4960-a1e5-4df1f73ac135","content":"<p>modern llama populations have a greater degree of genetic diversity, on average, than modern alpaca populations do.</p>"},{"id":"7256f215-0003-4df0-95c8-8e303e861d3f","content":"<p>the domestication process of the alpaca may have involved some introduction of genetic material from the llama.</p>"},{"id":"aa6fc7c7-2496-40b0-b318-97543da425a5","content":"<p>the period of interbreeding resulted in a greater genetic difference between alpacas and their wild ancestors than between llamas and their wild ancestors.</p>"},{"id":"d79fd1dc-f5d7-41f5-8e9b-f627102cf7b2","content":"<p>if they were subjected to genetic testing, modern populations of guanacos and vicu&ntilde;as would likely show traces of ancient interbreeding as well.</p>"}],"keys":["aa6fc7c7-2496-40b0-b318-97543da425a5"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it presents the inference that most logically follows from the text&rsquo;s discussion of the genetic material of alpacas. The text states that modern alpacas get only 64 percent of their genetic material from their wild ancestor (the vicu&ntilde;a), while llamas get 95.5 percent of their genetic material from their wild ancestor (the guanaco). These data imply that relative to llamas, alpacas have experienced a much greater genetic shift away from their wild ancestors (36 percent of their genetic material derives from another source, compared to 4.5 percent of llamas&rsquo; genetic material). Moreover, the text establishes that the remainder of alpacas&rsquo; genetic material derives from llamas, and the remainder of llamas&rsquo; genetic material derives from alpacas, reflecting a period of interbreeding. Taken together, these details support the inference that the period of interbreeding had a more significant impact on the genetic material of alpacas than on that of llamas, thereby reducing the percentage of alpacas&rsquo; genetic material that derives from wild ancestors and placing alpacas at a greater remove from these ancestors.</p><p>Choice A is incorrect because the text doesn&rsquo;t provide information about genetic diversity within modern llama and alpaca populations. While the text discusses the percentage of genetic material each domesticated species inherited from its wild ancestor and from interbreeding, it does not address the level of genetic variation within each species. Therefore, it isn&rsquo;t logical to infer that modern llama populations have a greater degree of genetic diversity than modern alpaca populations do. Choice B is incorrect because it contradicts the chronology presented in the text. The text states that alpacas were domesticated about 7,000 years ago, but the interbreeding with llamas occurred \"between 400 and 600 years ago.\" The genetic mixing happened thousands of years after domestication, not during it; in addition, the text does not provide details about what the process of domestication might entail. Therefore, it isn&rsquo;t logical to infer that llama genetic material was introduced during the domestication process of alpacas. Choice D is incorrect because though the text notes that guanacos and vicu&ntilde;as contributed to the genetic material of alpacas and llamas, it only discusses alpacas&rsquo; and llamas&rsquo; genetic composition. Therefore, the text does not support the inference that modern populations of guanacos and vicu&ntilde;as would likely show traces of ancient interbreeding.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061177,"updateDate":1755117061177}$SATQ$::jsonb, 1755117061177, 1755117061177),
    ($SATQ$4d38c2ea$SATQ$, $SATQ$17089083-33c6-4d4c-9f5d-eb517d0a9341$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Gorgets, or necklaces with large pendants, have been part of the ceremonial attire of tribes from the US Southeast for centuries. One of the oldest examples, the Fairfield Gorget, was found in Fairfield, Missouri, in 1958. Its overall design resembles that of other art from the region during the Mississippian period (900&ndash;1600 CE). Yet the image on the gorget is of a jaguar&mdash;a species whose range doesn&rsquo;t extend to Missouri. Jaguar images are common in ancient Mexican art, and Mexico lies squarely in the species&rsquo; range. Therefore, some scholars argue that <span style="text-decoration: underline;" role="region" aria-label="Referenced Content">long-distance trade in Mexican art objects brought the imagery to Missouri, where a local artist could have adopted it and incorporated it into the Fairfield Gorget.</span></p>$SATQ$, $SATQ$<p>Which finding, if true, would most strongly support the underlined explanation?</p>$SATQ$, $SATQ$[{"id":"442634c4-5cd8-4b72-9f67-1379d8b80186","content":"<p>The Fairfield Gorget is dated not to the Mississippian period but instead to the earlier Woodland period, which ended around 900 CE.</p>"},{"id":"ac663867-e386-4708-803a-e2d4262fceda","content":"<p>The range of the jaguar is shown to have expanded dramatically after the Mississippian period came to a close around 1600 CE.</p>"},{"id":"351372a4-4693-46b1-92d9-8aeb17aafc5a","content":"<p>An ancient Mexican art object is found at a site that dates to the Mississippian period and is close to where the Fairfield Gorget was found.</p>"},{"id":"0a95f49a-6e1f-485b-9746-e82fa7f7d626","content":"<p>Certain works by present-day artists from Southeastern tribes reflect outside cultural influences, including contemporary Mexican art.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["351372a4-4693-46b1-92d9-8aeb17aafc5a"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it presents a finding that, if true, would most strongly support the underlined explanation that the jaguar imagery on the Fairfield Gorget could have been inspired by art objects brought to Missouri from Mexico. The text describes the Fairfield Gorget as one of the oldest examples of these necklaces, noting that it&rsquo;s similar to other art from the Mississippian period except for its image of a jaguar. The text goes on to explain that this is unusual because the jaguar&rsquo;s range didn&rsquo;t include Missouri. The Fairfield Gorget&rsquo;s artist likely wouldn&rsquo;t have encountered a live jaguar, but since such jaguar images were common in ancient Mexican art (and the jaguar&rsquo;s range did include Mexico), perhaps some of that art inspired the gorget&rsquo;s artist. Therefore, evidence that an ancient Mexican art object had been found at a site that was close to the Fairfield Gorget in both location and time period would strongly support the explanation that long-distance trade from Mexico took place during the Mississippian period and that jaguar imagery could have reached Missouri by those means.</p><p>Choice A is incorrect. The underlined explanation indicates that Mexican artistic influence preceded the creation of the Fairfield Gorget. An artifact from Mexico that appeared in Missouri only after the gorget was created cannot support such a claim. Choice B is incorrect. The underlined explanation pertains to whether the jaguar image on the Fairfield Gorget was suggested to the Mississippian artist who made it by encounters with depictions of jaguars in Mexican art. The appearance of jaguars in Missouri after the Mississippian period cannot provide evidence for such a claim. Choice D is incorrect. The underlined explanation pertains to influence that Mexican art might have had on Mississippian art, restricted to the period from 900 CE to 1600 CE. The actions of contemporary artists cannot provide evidence for centuries-old networks of artistic influence and exchange.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"4d38c2ea","external_id":"17089083-33c6-4d4c-9f5d-eb517d0a9341","vaultid":null,"uId":"bc63d64b-a3c3-449c-9c84-0788750796c2","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Gorgets, or necklaces with large pendants, have been part of the ceremonial attire of tribes from the US Southeast for centuries. One of the oldest examples, the Fairfield Gorget, was found in Fairfield, Missouri, in 1958. Its overall design resembles that of other art from the region during the Mississippian period (900&ndash;1600 CE). Yet the image on the gorget is of a jaguar&mdash;a species whose range doesn&rsquo;t extend to Missouri. Jaguar images are common in ancient Mexican art, and Mexico lies squarely in the species&rsquo; range. Therefore, some scholars argue that <span style=\"text-decoration: underline;\" role=\"region\" aria-label=\"Referenced Content\">long-distance trade in Mexican art objects brought the imagery to Missouri, where a local artist could have adopted it and incorporated it into the Fairfield Gorget.</span></p>","stem":"<p>Which finding, if true, would most strongly support the underlined explanation?</p>","answerOptions":[{"id":"442634c4-5cd8-4b72-9f67-1379d8b80186","content":"<p>The Fairfield Gorget is dated not to the Mississippian period but instead to the earlier Woodland period, which ended around 900 CE.</p>"},{"id":"ac663867-e386-4708-803a-e2d4262fceda","content":"<p>The range of the jaguar is shown to have expanded dramatically after the Mississippian period came to a close around 1600 CE.</p>"},{"id":"351372a4-4693-46b1-92d9-8aeb17aafc5a","content":"<p>An ancient Mexican art object is found at a site that dates to the Mississippian period and is close to where the Fairfield Gorget was found.</p>"},{"id":"0a95f49a-6e1f-485b-9746-e82fa7f7d626","content":"<p>Certain works by present-day artists from Southeastern tribes reflect outside cultural influences, including contemporary Mexican art.</p>"}],"keys":["351372a4-4693-46b1-92d9-8aeb17aafc5a"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it presents a finding that, if true, would most strongly support the underlined explanation that the jaguar imagery on the Fairfield Gorget could have been inspired by art objects brought to Missouri from Mexico. The text describes the Fairfield Gorget as one of the oldest examples of these necklaces, noting that it&rsquo;s similar to other art from the Mississippian period except for its image of a jaguar. The text goes on to explain that this is unusual because the jaguar&rsquo;s range didn&rsquo;t include Missouri. The Fairfield Gorget&rsquo;s artist likely wouldn&rsquo;t have encountered a live jaguar, but since such jaguar images were common in ancient Mexican art (and the jaguar&rsquo;s range did include Mexico), perhaps some of that art inspired the gorget&rsquo;s artist. Therefore, evidence that an ancient Mexican art object had been found at a site that was close to the Fairfield Gorget in both location and time period would strongly support the explanation that long-distance trade from Mexico took place during the Mississippian period and that jaguar imagery could have reached Missouri by those means.</p><p>Choice A is incorrect. The underlined explanation indicates that Mexican artistic influence preceded the creation of the Fairfield Gorget. An artifact from Mexico that appeared in Missouri only after the gorget was created cannot support such a claim. Choice B is incorrect. The underlined explanation pertains to whether the jaguar image on the Fairfield Gorget was suggested to the Mississippian artist who made it by encounters with depictions of jaguars in Mexican art. The appearance of jaguars in Missouri after the Mississippian period cannot provide evidence for such a claim. Choice D is incorrect. The underlined explanation pertains to influence that Mexican art might have had on Mississippian art, restricted to the period from 900 CE to 1600 CE. The actions of contemporary artists cannot provide evidence for centuries-old networks of artistic influence and exchange.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323045,"updateDate":1730147323045}$SATQ$::jsonb, 1730147323045, 1730147323045),
    ($SATQ$4d3e3c52$SATQ$, $SATQ$fd02f4ff-6bf3-4885-92ba-dec5018038d6$SATQ$::uuid, $SATQ$f39f3005-6e93-48fe-92f0-094b80195248$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>In a paper about p-i-n planar perovskite solar cells (one of several perovskite cell architectures designed to collect and store solar power), Lyndsey McMillon-Brown et al. describe a method for fabricating the cell&rsquo;s electronic transport layer (ETL) using a spray coating. Conventional ETL fabrication is accomplished using a solution of nanoparticles. The process can result in a loss of up to 80% of the solution, increasing the cost of manufacturing at scale&mdash;an issue that may be obviated by spray coating fabrication, which the researchers describe as &ldquo;highly reproducible, concise, and practical.&rdquo;</p>$SATQ$, $SATQ$<p>What does the text most strongly suggest about conventional ETL fabrication?</p>$SATQ$, $SATQ$[{"id":"790767a5-3bf2-4798-9282-6aaffe254880","content":"<p>It is less suitable for manufacturing large volumes of planar p-i-n perovskite solar cells than an alternative fabrication method may be.</p>"},{"id":"2c2eb6de-4163-4282-9fee-4ba359e92e79","content":"<p>It is more expensive when manufacturing at scale than are processes for fabricating ETLs used in other perovskite solar cell architectures.</p>"},{"id":"f8014fde-b89a-4e7c-b025-7bbf447514a5","content":"<p>It typically entails a greater loss of nanoparticle solution than do other established approaches for ETL fabrication.</p>"},{"id":"7d499119-815e-4bc9-a60e-1543d15df7ad","content":"<p>It is somewhat imprecise and therefore limits the potential effectiveness of p-i-n planar perovskite solar cells at capturing and storing solar power.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["790767a5-3bf2-4798-9282-6aaffe254880"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. Conventional solar cell fabrication increases &ldquo;the cost of manufacturing at scale,&rdquo; but spray coating might get rid of that problem. </p><p>Choice B is incorrect. This is not completely supported by the text. While it&rsquo;s true that conventional ETL fabrication is expensive at scale, there&rsquo;s nothing in the text that mentions other perovskite solar cell architectures. Choice C is incorrect. This choice does not match the text. Only one conventional method of ETL fabrication is described, so we can&rsquo;t compare the solution loss in this method to that of other conventional methods.&nbsp;Choice D is incorrect. This choice isn&rsquo;t supported by the text. The text never suggests that the effectiveness of solar cells changes based on their method of fabrication. </p>$SATQ$, false, 0, $SATQ$OSP-KA-CID-H004$SATQ$, $SATQ$$SATQ$, $SATQ$380ee139-c547-4629-8e90-ccf8c4e583c5$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"4d3e3c52","external_id":"fd02f4ff-6bf3-4885-92ba-dec5018038d6","vaultid":"f39f3005-6e93-48fe-92f0-094b80195248","uId":"763041b9-f575-40a1-9f18-07c848c2ce00","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>In a paper about p-i-n planar perovskite solar cells (one of several perovskite cell architectures designed to collect and store solar power), Lyndsey McMillon-Brown et al. describe a method for fabricating the cell&rsquo;s electronic transport layer (ETL) using a spray coating. Conventional ETL fabrication is accomplished using a solution of nanoparticles. The process can result in a loss of up to 80% of the solution, increasing the cost of manufacturing at scale&mdash;an issue that may be obviated by spray coating fabrication, which the researchers describe as &ldquo;highly reproducible, concise, and practical.&rdquo;</p>","stem":"<p>What does the text most strongly suggest about conventional ETL fabrication?</p>","answerOptions":[{"id":"790767a5-3bf2-4798-9282-6aaffe254880","content":"<p>It is less suitable for manufacturing large volumes of planar p-i-n perovskite solar cells than an alternative fabrication method may be.</p>"},{"id":"2c2eb6de-4163-4282-9fee-4ba359e92e79","content":"<p>It is more expensive when manufacturing at scale than are processes for fabricating ETLs used in other perovskite solar cell architectures.</p>"},{"id":"f8014fde-b89a-4e7c-b025-7bbf447514a5","content":"<p>It typically entails a greater loss of nanoparticle solution than do other established approaches for ETL fabrication.</p>"},{"id":"7d499119-815e-4bc9-a60e-1543d15df7ad","content":"<p>It is somewhat imprecise and therefore limits the potential effectiveness of p-i-n planar perovskite solar cells at capturing and storing solar power.</p>"}],"keys":["790767a5-3bf2-4798-9282-6aaffe254880"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. Conventional solar cell fabrication increases &ldquo;the cost of manufacturing at scale,&rdquo; but spray coating might get rid of that problem. </p><p>Choice B is incorrect. This is not completely supported by the text. While it&rsquo;s true that conventional ETL fabrication is expensive at scale, there&rsquo;s nothing in the text that mentions other perovskite solar cell architectures. Choice C is incorrect. This choice does not match the text. Only one conventional method of ETL fabrication is described, so we can&rsquo;t compare the solution loss in this method to that of other conventional methods.&nbsp;Choice D is incorrect. This choice isn&rsquo;t supported by the text. The text never suggests that the effectiveness of solar cells changes based on their method of fabrication. </p>","parenttemplatename":"OSP-KA-CID-H004","parenttemplateid":"","templateclusterid":"380ee139-c547-4629-8e90-ccf8c4e583c5","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959360,"updateDate":1691007959360}$SATQ$::jsonb, 1691007959360, 1691007959360),
    ($SATQ$4e9afd7a$SATQ$, $SATQ$bf6639e8-1ad9-4de8-a308-e9f22045c036$SATQ$::uuid, $SATQ$4f174fe0-5439-47e5-89af-897aa5014e54$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>The Indus River valley civilization flourished in South Asia from 3300 BCE to 1300 BCE. Many examples of the civilization&rsquo;s writing system exist, but researchers haven&rsquo;t yet deciphered it or identified which ancient language it represents. Nevertheless, archaeologists have found historical artifacts, such as clay figures and jewelry, that provide information about the civilization&rsquo;s customs and how its communities were organized. The archaeologists&rsquo; findings therefore suggest that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"a3af9e8f-f99e-4bbc-b76b-6a33b1597bf2","content":"<p>investigating an ancient civilization is easier without knowledge of the civilization&rsquo;s language.</p>"},{"id":"bf3d98d1-b805-4a71-b979-a85a480d0bee","content":"<p>knowing an ancient civilization&rsquo;s language isn&rsquo;t necessary in order to learn details about the civilization.</p>"},{"id":"45f33a7b-ca30-4f0f-9e3e-f3c7845bd1b0","content":"<p>archaeological research should focus on finding additional artifacts rather than deciphering ancient languages.</p>"},{"id":"5c59ba84-8092-4e0d-92c0-4a7006283e49","content":"<p>examining the civilization&rsquo;s historical artifacts has resolved the debate about this civilization&rsquo;s language.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["bf3d98d1-b805-4a71-b979-a85a480d0bee"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of the Indus River valley civilization. The text establishes that archaeologists haven&rsquo;t been able to interpret the Indus River valley civilization&rsquo;s writing system but have nevertheless acquired information about the civilization through historical artifacts. The fact that archaeologists have been able to learn about the Indus River valley civilization&rsquo;s customs and community organization from historical artifacts suggests that it isn&rsquo;t necessary to understand an ancient civilization&rsquo;s language to learn about the civilization. </p><p>Choice A is incorrect because the text doesn&rsquo;t discuss how easy it is to investigate ancient civilizations with or without knowledge of the civilization&rsquo;s language; rather, it states that even though researchers have not yet deciphered the language of the Indus River valley civilization, they are still able to learn about it through historical artifacts.&nbsp;Choice C is incorrect because the text doesn&rsquo;t make any claims as to what the focus of archaeological research should be. Rather, the text discusses how archaeologists have been able to learn about an ancient civilization through historical artifacts despite not understanding the civilization&rsquo;s language.&nbsp;Choice D is incorrect because the text states that the civilization&rsquo;s language has not yet been interpreted; it makes no mention of a debate about the language. Instead, the text suggests that examination of the historical artifacts has allowed archaeologists to learn about the civilization but has not aided thus far in deciphering its language.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-047-INF$SATQ$, $SATQ$$SATQ$, $SATQ$97f4782f-d64d-466f-89dd-68f49aca7e90$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"4e9afd7a","external_id":"bf6639e8-1ad9-4de8-a308-e9f22045c036","vaultid":"4f174fe0-5439-47e5-89af-897aa5014e54","uId":"6a4249e0-0fdd-4b11-b426-f72545eba362","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>The Indus River valley civilization flourished in South Asia from 3300 BCE to 1300 BCE. Many examples of the civilization&rsquo;s writing system exist, but researchers haven&rsquo;t yet deciphered it or identified which ancient language it represents. Nevertheless, archaeologists have found historical artifacts, such as clay figures and jewelry, that provide information about the civilization&rsquo;s customs and how its communities were organized. The archaeologists&rsquo; findings therefore suggest that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"a3af9e8f-f99e-4bbc-b76b-6a33b1597bf2","content":"<p>investigating an ancient civilization is easier without knowledge of the civilization&rsquo;s language.</p>"},{"id":"bf3d98d1-b805-4a71-b979-a85a480d0bee","content":"<p>knowing an ancient civilization&rsquo;s language isn&rsquo;t necessary in order to learn details about the civilization.</p>"},{"id":"45f33a7b-ca30-4f0f-9e3e-f3c7845bd1b0","content":"<p>archaeological research should focus on finding additional artifacts rather than deciphering ancient languages.</p>"},{"id":"5c59ba84-8092-4e0d-92c0-4a7006283e49","content":"<p>examining the civilization&rsquo;s historical artifacts has resolved the debate about this civilization&rsquo;s language.</p>"}],"keys":["bf3d98d1-b805-4a71-b979-a85a480d0bee"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of the Indus River valley civilization. The text establishes that archaeologists haven&rsquo;t been able to interpret the Indus River valley civilization&rsquo;s writing system but have nevertheless acquired information about the civilization through historical artifacts. The fact that archaeologists have been able to learn about the Indus River valley civilization&rsquo;s customs and community organization from historical artifacts suggests that it isn&rsquo;t necessary to understand an ancient civilization&rsquo;s language to learn about the civilization. </p><p>Choice A is incorrect because the text doesn&rsquo;t discuss how easy it is to investigate ancient civilizations with or without knowledge of the civilization&rsquo;s language; rather, it states that even though researchers have not yet deciphered the language of the Indus River valley civilization, they are still able to learn about it through historical artifacts.&nbsp;Choice C is incorrect because the text doesn&rsquo;t make any claims as to what the focus of archaeological research should be. Rather, the text discusses how archaeologists have been able to learn about an ancient civilization through historical artifacts despite not understanding the civilization&rsquo;s language.&nbsp;Choice D is incorrect because the text states that the civilization&rsquo;s language has not yet been interpreted; it makes no mention of a debate about the language. Instead, the text suggests that examination of the historical artifacts has allowed archaeologists to learn about the civilization but has not aided thus far in deciphering its language.&nbsp;</p>","parenttemplatename":"OSP-047-INF","parenttemplateid":"","templateclusterid":"97f4782f-d64d-466f-89dd-68f49aca7e90","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959323,"updateDate":1691007959323}$SATQ$::jsonb, 1691007959323, 1691007959323),
    ($SATQ$4f9f8ea6$SATQ$, $SATQ$591eb366-0d71-42a1-b86b-8b17f03a42c2$SATQ$::uuid, $SATQ$9245b365-09d2-4dba-b095-36e5aa415580$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Birds of many species ingest foods containing carotenoids, pigmented molecules that are converted into feather coloration. Coloration tends to be especially saturated in male birds&rsquo; feathers, and because carotenoids also confer health benefits, the deeply saturated colors generally serve to communicate what is known as an honest signal of a bird&rsquo;s overall fitness to potential mates. However, ornithologist Allison J. Shultz and others have found that males in several species of the tanager genus <em>Ramphocelus</em> use microstructures in their feathers to manipulate light, creating the appearance of deeper saturation without the birds necessarily having to maintain a carotenoid-rich diet. These findings suggest that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"20ca5293-d545-45f9-80e6-c5b41a6b5dfb","content":"<p>individual male tanagers can engage in honest signaling without relying on carotenoid consumption.</p>"},{"id":"98fab16b-1e41-4374-b614-2f492e3309b3","content":"<p>feather microstructures may be less effective than deeply saturated feathers for signaling overall fitness.</p>"},{"id":"2eb9adbc-0804-4aed-9e93-58a42346a361","content":"<p>scientists have yet to determine why tanagers have a preference for mates with colorful appearances.</p>"},{"id":"bc8b90d3-0f86-466f-934e-24ee2896efa1","content":"<p>a male tanager&rsquo;s appearance may function as a dishonest signal of the individual&rsquo;s overall fitness.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["bc8b90d3-0f86-466f-934e-24ee2896efa1"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of Shultz&rsquo;s finding about male tanagers. The text explains that because carotenoids both contribute to deeply saturated feathers and offer health benefits, having deeply saturated feathers is usually &ldquo;an honest signal&rdquo; (a true indication) that a bird is generally fit. However, Shultz and others have found that certain male tanagers can appear to have deeply saturated feathers even if they haven&rsquo;t consumed a diet rich in carotenoids, thanks to microstructures in their feathers that manipulate light. If those birds aren&rsquo;t necessarily eating carotenoid-rich diets, they may actually be less fit than other birds that appear to have similarly saturated feathers; this suggests that a male tanager&rsquo;s appearance may function as a dishonest signal, or a false indication, of the bird&rsquo;s overall fitness.&nbsp;</p><p>Choice A is incorrect because Shultz&rsquo;s finding suggests that some tanagers can signal fitness without consuming the carotenoids that contribute to fitness, thereby making those signals dishonest, not that tanagers can give honest signals of their fitness without consuming carotenoids.&nbsp;Choice B is incorrect because Shultz&rsquo;s finding suggests that the microstructures in certain tanagers&rsquo; feathers can give a dishonest signal of fitness, not that the microstructures are less effective than actual pigmentation for signaling fitness. Whether the signal of fitness is honest or dishonest has no bearing on how effective the signal is: a signal is effective if potential mates behave as though it&rsquo;s true, regardless of whether it&rsquo;s actually true. Since there&rsquo;s no information in the text about how potential mates respond to the dishonest signals of some tanagers, there&rsquo;s no support for the idea that the dishonest signals are less effective than the honest signals.&nbsp;Choice C is incorrect because Shultz&rsquo;s finding suggests that certain male tanagers may appear to be fitter than they actually are, not that scientists haven&rsquo;t determined why tanagers prefer mates with colorful appearances.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-020-INF$SATQ$, $SATQ$$SATQ$, $SATQ$ae799a7b-47fa-4b0d-ab5a-9289e2e27224$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"4f9f8ea6","external_id":"591eb366-0d71-42a1-b86b-8b17f03a42c2","vaultid":"9245b365-09d2-4dba-b095-36e5aa415580","uId":"ab85e6a3-2be9-45ad-96cb-71003a157f2b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Birds of many species ingest foods containing carotenoids, pigmented molecules that are converted into feather coloration. Coloration tends to be especially saturated in male birds&rsquo; feathers, and because carotenoids also confer health benefits, the deeply saturated colors generally serve to communicate what is known as an honest signal of a bird&rsquo;s overall fitness to potential mates. However, ornithologist Allison J. Shultz and others have found that males in several species of the tanager genus <em>Ramphocelus</em> use microstructures in their feathers to manipulate light, creating the appearance of deeper saturation without the birds necessarily having to maintain a carotenoid-rich diet. These findings suggest that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"20ca5293-d545-45f9-80e6-c5b41a6b5dfb","content":"<p>individual male tanagers can engage in honest signaling without relying on carotenoid consumption.</p>"},{"id":"98fab16b-1e41-4374-b614-2f492e3309b3","content":"<p>feather microstructures may be less effective than deeply saturated feathers for signaling overall fitness.</p>"},{"id":"2eb9adbc-0804-4aed-9e93-58a42346a361","content":"<p>scientists have yet to determine why tanagers have a preference for mates with colorful appearances.</p>"},{"id":"bc8b90d3-0f86-466f-934e-24ee2896efa1","content":"<p>a male tanager&rsquo;s appearance may function as a dishonest signal of the individual&rsquo;s overall fitness.</p>"}],"keys":["bc8b90d3-0f86-466f-934e-24ee2896efa1"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of Shultz&rsquo;s finding about male tanagers. The text explains that because carotenoids both contribute to deeply saturated feathers and offer health benefits, having deeply saturated feathers is usually &ldquo;an honest signal&rdquo; (a true indication) that a bird is generally fit. However, Shultz and others have found that certain male tanagers can appear to have deeply saturated feathers even if they haven&rsquo;t consumed a diet rich in carotenoids, thanks to microstructures in their feathers that manipulate light. If those birds aren&rsquo;t necessarily eating carotenoid-rich diets, they may actually be less fit than other birds that appear to have similarly saturated feathers; this suggests that a male tanager&rsquo;s appearance may function as a dishonest signal, or a false indication, of the bird&rsquo;s overall fitness.&nbsp;</p><p>Choice A is incorrect because Shultz&rsquo;s finding suggests that some tanagers can signal fitness without consuming the carotenoids that contribute to fitness, thereby making those signals dishonest, not that tanagers can give honest signals of their fitness without consuming carotenoids.&nbsp;Choice B is incorrect because Shultz&rsquo;s finding suggests that the microstructures in certain tanagers&rsquo; feathers can give a dishonest signal of fitness, not that the microstructures are less effective than actual pigmentation for signaling fitness. Whether the signal of fitness is honest or dishonest has no bearing on how effective the signal is: a signal is effective if potential mates behave as though it&rsquo;s true, regardless of whether it&rsquo;s actually true. Since there&rsquo;s no information in the text about how potential mates respond to the dishonest signals of some tanagers, there&rsquo;s no support for the idea that the dishonest signals are less effective than the honest signals.&nbsp;Choice C is incorrect because Shultz&rsquo;s finding suggests that certain male tanagers may appear to be fitter than they actually are, not that scientists haven&rsquo;t determined why tanagers prefer mates with colorful appearances.&nbsp;</p>","parenttemplatename":"OSP-020-INF","parenttemplateid":"","templateclusterid":"ae799a7b-47fa-4b0d-ab5a-9289e2e27224","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959317,"updateDate":1691007959317}$SATQ$::jsonb, 1691007959317, 1691007959317),
    ($SATQ$4fc9a13a$SATQ$, $SATQ$35ba1503-3ca4-4444-aa35-a1bfdee283cf$SATQ$::uuid, $SATQ$05015490-c8d3-4998-90fb-7cb172705c99$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>The novelist Toni Morrison was the first Black woman to work as an editor at the publishing company Random House, from 1967 to 1983. A scholar asserts that one of Morrison&rsquo;s likely aims during her time as an editor was to strengthen the presence of Black writers on the list of Random House&rsquo;s published authors.</p>$SATQ$, $SATQ$<p>Which finding, if true, would most strongly support the scholar&rsquo;s claim?</p>$SATQ$, $SATQ$[{"id":"864dba93-55cf-470a-be4c-c0b10f1f4795","content":"<p>The percentage of authors published by Random House who were Black rose in the early 1970s and stabilized throughout the decade.</p>"},{"id":"ab5cebbc-646d-45b0-9631-315922fe0182","content":"<p>Black authors who were interviewed in the 1980s and 1990s were highly likely to cite Toni Morrison&rsquo;s novels as a principal influence on their work.</p>"},{"id":"d436dcdb-be45-4e7d-8b05-c2a5c1a86b92","content":"<p>The novels written by Toni Morrison that were published after 1983 sold significantly more copies and received wider critical acclaim than the novels she wrote that were published before 1983.</p>"},{"id":"fa51c530-b09f-4cbf-84d6-a1e987ae6bc8","content":"<p>Works that were edited by Toni Morrison during her time at Random House displayed stylistic characteristics that distinguished them from works that were not edited by Morrison.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["864dba93-55cf-470a-be4c-c0b10f1f4795"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it presents a finding that, if true, would support the scholar&rsquo;s claim about Toni Morrison&rsquo;s likely goal of strengthening the presence of Black writers on Random House&rsquo;s list of published authors. The text explains that Morrison was the first Black woman to be an editor for Random House and that she was an editor there from 1967 to 1983. If it were true that Random House published a higher percentage of works by Black authors throughout the 1970s&mdash;during most of Morrison&rsquo;s time working there&mdash;than it had previously published, that would suggest that Morrison may have made a deliberate effort to strengthen the presence of Black authors on the list of Random House&rsquo;s published authors, thus supporting the scholar&rsquo;s claim. </p><p>Choice B is incorrect because the scholar&rsquo;s claim is about Morrison&rsquo;s work as an editor at a publishing company and her likely effort to strengthen the presence of Black writers on that company&rsquo;s list of published authors. It might be true that Black authors interviewed in the 1980s and 1990s often cited Morrison&rsquo;s novels as an influence on their work, but that finding would simply suggest something about how those authors approached their work; it wouldn&rsquo;t show that Morrison intended to increase the number of Black writers among the published authors specifically at Random House. Choice C is incorrect because the scholar&rsquo;s claim is about Morrison&rsquo;s work as an editor at a publishing company, not about her work as a novelist. Therefore, a finding that Morrison&rsquo;s novels published after 1983 sold more copies and were more widely acclaimed than her earlier novels would have no bearing on the claim that as an editor Morrison made an effort to ensure that more Black writers were present on Random House&rsquo;s list of published authors. Choice D is incorrect. Although the text discusses Morrison&rsquo;s work as an editor at Random House, the scholar&rsquo;s claim focuses on Morrison&rsquo;s likely effort in that role to increase the number of Black writers present on Random House&rsquo;s list of published authors, not on the influence she may have had on the content of the works she edited. Without knowing whether Morrison&rsquo;s stylistic influence led to more publications or if Morrison applied her influence specifically to works by Black writers, the finding that works edited by Morrison could be identified by stylistic characteristics would have no bearing on the claim that Morrison intended to strengthen the presence of Black writers among the published authors at Random House. </p>$SATQ$, false, 0, $SATQ$OSP-305-TXT$SATQ$, $SATQ$$SATQ$, $SATQ$381adcbe-d7f9-4229-b83f-e74a945aef5f$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"4fc9a13a","external_id":"35ba1503-3ca4-4444-aa35-a1bfdee283cf","vaultid":"05015490-c8d3-4998-90fb-7cb172705c99","uId":"f63f0724-93e0-4e0b-91f2-e1965c712e86","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>The novelist Toni Morrison was the first Black woman to work as an editor at the publishing company Random House, from 1967 to 1983. A scholar asserts that one of Morrison&rsquo;s likely aims during her time as an editor was to strengthen the presence of Black writers on the list of Random House&rsquo;s published authors.</p>","stem":"<p>Which finding, if true, would most strongly support the scholar&rsquo;s claim?</p>","answerOptions":[{"id":"864dba93-55cf-470a-be4c-c0b10f1f4795","content":"<p>The percentage of authors published by Random House who were Black rose in the early 1970s and stabilized throughout the decade.</p>"},{"id":"ab5cebbc-646d-45b0-9631-315922fe0182","content":"<p>Black authors who were interviewed in the 1980s and 1990s were highly likely to cite Toni Morrison&rsquo;s novels as a principal influence on their work.</p>"},{"id":"d436dcdb-be45-4e7d-8b05-c2a5c1a86b92","content":"<p>The novels written by Toni Morrison that were published after 1983 sold significantly more copies and received wider critical acclaim than the novels she wrote that were published before 1983.</p>"},{"id":"fa51c530-b09f-4cbf-84d6-a1e987ae6bc8","content":"<p>Works that were edited by Toni Morrison during her time at Random House displayed stylistic characteristics that distinguished them from works that were not edited by Morrison.</p>"}],"keys":["864dba93-55cf-470a-be4c-c0b10f1f4795"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it presents a finding that, if true, would support the scholar&rsquo;s claim about Toni Morrison&rsquo;s likely goal of strengthening the presence of Black writers on Random House&rsquo;s list of published authors. The text explains that Morrison was the first Black woman to be an editor for Random House and that she was an editor there from 1967 to 1983. If it were true that Random House published a higher percentage of works by Black authors throughout the 1970s&mdash;during most of Morrison&rsquo;s time working there&mdash;than it had previously published, that would suggest that Morrison may have made a deliberate effort to strengthen the presence of Black authors on the list of Random House&rsquo;s published authors, thus supporting the scholar&rsquo;s claim. </p><p>Choice B is incorrect because the scholar&rsquo;s claim is about Morrison&rsquo;s work as an editor at a publishing company and her likely effort to strengthen the presence of Black writers on that company&rsquo;s list of published authors. It might be true that Black authors interviewed in the 1980s and 1990s often cited Morrison&rsquo;s novels as an influence on their work, but that finding would simply suggest something about how those authors approached their work; it wouldn&rsquo;t show that Morrison intended to increase the number of Black writers among the published authors specifically at Random House. Choice C is incorrect because the scholar&rsquo;s claim is about Morrison&rsquo;s work as an editor at a publishing company, not about her work as a novelist. Therefore, a finding that Morrison&rsquo;s novels published after 1983 sold more copies and were more widely acclaimed than her earlier novels would have no bearing on the claim that as an editor Morrison made an effort to ensure that more Black writers were present on Random House&rsquo;s list of published authors. Choice D is incorrect. Although the text discusses Morrison&rsquo;s work as an editor at Random House, the scholar&rsquo;s claim focuses on Morrison&rsquo;s likely effort in that role to increase the number of Black writers present on Random House&rsquo;s list of published authors, not on the influence she may have had on the content of the works she edited. Without knowing whether Morrison&rsquo;s stylistic influence led to more publications or if Morrison applied her influence specifically to works by Black writers, the finding that works edited by Morrison could be identified by stylistic characteristics would have no bearing on the claim that Morrison intended to strengthen the presence of Black writers among the published authors at Random House. </p>","parenttemplatename":"OSP-305-TXT","parenttemplateid":"","templateclusterid":"381adcbe-d7f9-4229-b83f-e74a945aef5f","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959335,"updateDate":1691007959335}$SATQ$::jsonb, 1691007959335, 1691007959335)
